window.SB_FEED_BODY=window.SB_FEED_BODY||{},Object.assign(window.SB_FEED_BODY,{"wd-gargantuan":{src:"concept:106:words:6:def",route:"#/word/gargantuan",cta:"Open the word card",title:"gargantuan",roman:"gah-RGA-nchoo-uhn",body:"of great mass; huge and bulky",clip:1},"wx-gargantuan":{src:"concept:106:words:6:ex",route:"#/word/gargantuan",cta:"Open the word card",title:"In a sentence · gargantuan",body:"The gargantuan sandwich at the deli was so tall that you needed two hands just to hold it up.",clip:1},"wh-gargantuan":{src:"concept:106:words:6:hook",route:"#/word/gargantuan",cta:"Open the word card",title:"Remember it · gargantuan",body:"GARGANTuan — a GIANT name for a GIANT size"},"wo-gargantuan":{src:"lore:gargantuan:0",route:"#/word/gargantuan",cta:"Open the word card",title:"Where it comes from · gargantuan",body:"French Gargantua = a giant in Rabelais's 16th-century novel, likely from gargate = throat"},"wx-elephantine":{src:"concept:106:words:8:ex",route:"#/word/elephantine",cta:"Open the word card",title:"In a sentence · elephantine",body:"The elephantine boulders that blocked the mountain trail had been carried there by a glacier thousands of years ago and were far too massive for any crew to move.",clip:1},"wh-elephantine":{src:"concept:106:words:8:hook",route:"#/word/elephantine",cta:"Open the word card",title:"Remember it · elephantine",body:"ELEPHANTINE ends in -INE like a magazine — imagine a magazine called 'Elephant INE' for giant things."},"wo-elephantine":{src:"lore:elephantine:0",route:"#/word/elephantine",cta:"Open the word card",title:"Where it comes from · elephantine",body:"Greek elephantinos = of ivory, of elephant"},"wd-myriad":{src:"concept:106:words:10:def",route:"#/word/myriad",cta:"Open the word card",title:"myriad",roman:"m-IH-r-ee-uh-d",body:"a very great or indefinitely great number",clip:1},"wx-myriad":{src:"concept:106:words:10:ex",route:"#/word/myriad",cta:"Open the word card",title:"In a sentence · myriad",body:"he faced a myriad of details",clip:1},"wh-myriad":{src:"concept:106:words:10:hook",route:"#/word/myriad",cta:"Open the word card",title:"Remember it · myriad",body:"A MYRIAD of stars: MY Reliable Infinite Array of Dots — M-Y-R-I-A-D."},"wo-myriad":{src:"lore:myriad:0",route:"#/word/myriad",cta:"Open the word card",title:"Where it comes from · myriad",body:"Greek myrias=ten thousand, countless"},"wd-plethora":{src:"concept:106:words:11:def",route:"#/word/plethora",cta:"Open the word card",title:"plethora",roman:"PLEH-ther-uh",body:"extreme excess",clip:1},"wx-plethora":{src:"concept:106:words:11:ex",route:"#/word/plethora",cta:"Open the word card",title:"In a sentence · plethora",body:"There was a plethora of science fair projects on volcanoes, so the judges decided to award a special prize for the most original topic.",clip:1},"wh-plethora":{src:"concept:106:words:11:hook",route:"#/word/plethora",cta:"Open the word card",title:"Remember it · plethora",body:"PLETH-ORA: think of PLENTY of things OVERFLOWING into a PLETH-ora!"},"wo-plethora":{src:"lore:plethora:0",route:"#/word/plethora",cta:"Open the word card",title:"Where it comes from · plethora",body:"Greek plethora = fullness, from plethein (to be full)"},"wd-paucity":{src:"concept:106:words:12:def",route:"#/word/paucity",cta:"Open the word card",title:"paucity",roman:"PAW-suh-tee",body:"the presence of something in only small or insufficient quantities",clip:1},"wx-paucity":{src:"concept:106:words:12:ex",route:"#/word/paucity",cta:"Open the word card",title:"In a sentence · paucity",body:"Because of the paucity of rain that summer, the reservoir dropped to dangerously low levels and water rationing began.",clip:1},"wh-paucity":{src:"concept:106:words:12:hook",route:"#/word/paucity",cta:"Open the word card",title:"Remember it · paucity",body:"PAUCITY: PAUSE and think how LITTLE (paucus) there is—a PAUSE means something is missing"},"wd-dearth":{src:"concept:106:words:13:def",route:"#/word/dearth",cta:"Open the word card",title:"dearth",roman:"DURTH",body:"an acute insufficiency",clip:1},"wx-dearth":{src:"concept:106:words:13:ex",route:"#/word/dearth",cta:"Open the word card",title:"In a sentence · dearth",body:"There was such a dearth of rain that summer that the farmers feared their crops would completely wither.",clip:1},"wh-dearth":{src:"concept:106:words:13:hook",route:"#/word/dearth",cta:"Open the word card",title:"Remember it · dearth",body:"A DEARTH of ideas? Picture the EAR in dEARth — you can't HEAR any ideas because there are so few."},"wd-negligible":{src:"concept:106:words:14:def",route:"#/word/negligible",cta:"Open the word card",title:"negligible",roman:"NEH-gluh-juh-buhl",body:"so small as to be meaningless; insignificant",clip:1},"wx-negligible":{src:"concept:106:words:14:ex",route:"#/word/negligible",cta:"Open the word card",title:"In a sentence · negligible",body:"the effect was negligible",clip:1},"wh-negligible":{src:"concept:106:words:14:hook",route:"#/word/negligible",cta:"Open the word card",title:"Remember it · negligible",body:"A negligIBLE amount can be neglIgIBly ignored — use '-ible' like 'possible.'"},"wo-negligible":{src:"lore:negligible:0",route:"#/word/negligible",cta:"Open the word card",title:"Where it comes from · negligible",body:"Latin neglegere = to disregard"},"li-u106":{src:"concept:109:concept",route:"#/stop/u106",cta:"Open this stop",title:"Words About Knowledge & Learning",body:"The vocabulary of learning, knowledge, and ignorance draws from Greek mathein (learn), Latin docere (teach), and scire (know). These words describe the pursuit of understanding itself."},"lc-u106-0":{src:"concept:109:cards:0",route:"#/stop/u106",cta:"Open this stop",title:"Words About Knowledge & Learning · The Teaching Roots",body:"Erudite (e- + rudis = rough = polished by learning). Pedagogy (pais = child + agein = lead) = the science of teaching. Didactic (didaskein = to teach) = intended to teach or instruct. Edification (e- + aedificare = build) = mental or moral improvement."},"lc-u106-1":{src:"concept:109:cards:1",route:"#/stop/u106",cta:"Open this stop",title:"Words About Knowledge & Learning · Knowledge vs Ignorance",body:'Omniscient = knows everything. Prescient = knows in advance. Nescient (ne- = not + scire) = lacking knowledge. Obtuse = slow to understand. Ignoramus (Latin legal term = "we do not know") = an ignorant person. Troglodyte (trogle = cave + dytes = one who enters) = one who is behind the times.'},"lc-u106-2":{src:"concept:109:cards:2",route:"#/stop/u106",cta:"Open this stop",title:"Words About Knowledge & Learning · Academic Vocabulary",body:"Dissertation (dis- + serere = to join = a connected argument) = a scholarly essay. Exegesis (exegeisthai = to lead out the meaning) = scholarly interpretation of a text. Hermeneutics (from Hermes, the interpreter) = the theory of interpretation."},"lc-u106-3":{src:"concept:109:cards:3",route:"#/stop/u106",cta:"Open this stop",title:"Words About Knowledge & Learning · Learning Methods",body:"Autodidact (auto- + didakt-) = self-taught. Empirical (empeiria = experience) = based on evidence and experience. Deductive = reasoning from general principles to specific cases. Inductive = reasoning from specific cases to general principles."},"lc-u106-4":{src:"concept:109:cards:4",route:"#/stop/u106",cta:"Open this stop",title:"Words About Knowledge & Learning · Spelling Knowledge Words",body:"Erudite = E-R-U-D-I-T-E (-ite not -ight). Pedagogy = P-E-D-A-G-O-G-Y. Didactic = D-I-D-A-C-T-I-C. Heuristic = H-E-U-R-I-S-T-I-C (-eu- diphthong). Exegesis = E-X-E-G-E-S-I-S (-esis Greek suffix). Hermeneutics = H-E-R-M-E-N-E-U-T-I-C-S (-eu- twice)."},"uq-u106-0":{src:"unit:u106:qs:0",route:"#/stop/u106",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Words About Knowledge & Learning”?",opts:["The vocabulary of learning, knowledge, and ignorance draws from Greek mathein (learn), Latin docere (teach), and scire (know).","Contronyms (also called autoantonyms) are words with two opposite meanings.","Latin re- = again or back.","Latin trans- = across, beyond, or through complete change."],after:"From “Words About Knowledge & Learning”."}},"uq-u106-3":{src:"unit:u106:qs:3",route:"#/stop/u106",cta:"Open this stop",title:"Whose hook?",play:{q:"“An ▁▁▁ scholar is polished OUT of being RUDE and RAW—refined by knowledge.” — which word is this hook about?",opts:["erudite","pedagogy","didactic","edification"],after:"From “Words About Knowledge & Learning”."}},"wd-erudite":{src:"concept:109:words:0:def",route:"#/word/erudite",cta:"Open the word card",title:"erudite",roman:"EH-ruh-deyet",body:"having or showing profound knowledge",clip:1},"wx-erudite":{src:"concept:109:words:0:ex",route:"#/word/erudite",cta:"Open the word card",title:"In a sentence · erudite",body:"The erudite professor could speak fluently about ancient languages, modern physics, and Renaissance art all within a single lecture, leaving her students both deeply inspired and slightly overwhelmed.",clip:1},"wh-erudite":{src:"concept:109:words:0:hook",route:"#/word/erudite",cta:"Open the word card",title:"Remember it · erudite",body:"An ERUdite scholar is polished OUT of being RUDE and RAW—refined by knowledge."},"wd-pedagogy":{src:"concept:109:words:1:def",route:"#/word/pedagogy",cta:"Open the word card",title:"pedagogy",roman:"PEH-duh-goh-jee",body:"the principles and methods of instruction",clip:1},"wx-pedagogy":{src:"concept:109:words:1:ex",route:"#/word/pedagogy",cta:"Open the word card",title:"In a sentence · pedagogy",body:"Miss Okafor studies pedagogy so she can teach fractions in a way children remember.",clip:1},"wh-pedagogy":{src:"concept:109:words:1:hook",route:"#/word/pedagogy",cta:"Open the word card",title:"Remember it · pedagogy",body:"PEDAGOGY is the art of leading children to knowledge — PED+AGOG+Y; don't double the GO, one is enough."},"wo-pedagogy":{src:"lore:pedagogy:0",route:"#/word/pedagogy",cta:"Open the word card",title:"Where it comes from · pedagogy",body:"Greek paidagogía = education; pais = child + agogos = leader"},"wd-didactic":{src:"concept:109:words:2:def",route:"#/word/didactic",cta:"Open the word card",title:"didactic",roman:"deye-DA-ktihk",body:"instructive (especially excessively)",clip:1},"wx-didactic":{src:"concept:109:words:2:ex",route:"#/word/didactic",cta:"Open the word card",title:"In a sentence · didactic",body:"Although the novel had an important moral lesson, its tone was so didactic that many readers felt they were being lectured rather than entertained.",clip:1},"wh-didactic":{src:"concept:109:words:2:hook",route:"#/word/didactic",cta:"Open the word card",title:"Remember it · didactic",body:"DIDACTIC teaching DID ACT on students — the teacher DID ACT to instruct them."},"wo-didactic":{src:"lore:didactic:0",route:"#/word/didactic",cta:"Open the word card",title:"Where it comes from · didactic",body:"Greek didaktikos = apt at teaching, from didaskein = to teach"},"wd-edification":{src:"concept:109:words:3:def",route:"#/word/edification",cta:"Open the word card",title:"edification",roman:"eh-duh-fuh-KAY-shuhn",body:"uplifting enlightenment",clip:1},"wx-edification":{src:"concept:109:words:3:ex",route:"#/word/edification",cta:"Open the word card",title:"In a sentence · edification",body:"The principal posted inspirational quotes in the hallway for the edification of every student who passed by.",clip:1},"wh-edification":{src:"concept:109:words:3:hook",route:"#/word/edification",cta:"Open the word card",title:"Remember it · edification",body:"EDIFication EDIFIES — like building an EDIFICE, it builds up your mind."},"wo-edification":{src:"lore:edification:0",route:"#/word/edification",cta:"Open the word card",title:"Where it comes from · edification",body:"Latin aedificare = to build, from aedes = building + facere = to make"},"wd-heuristic":{src:"concept:109:words:4:def",route:"#/word/heuristic",cta:"Open the word card",title:"heuristic",roman:"hyuu-RIH-stihk",body:"a commonsense rule (or set of rules) intended to increase the probability of solving some problem",clip:1},"wx-heuristic":{src:"concept:109:words:4:ex",route:"#/word/heuristic",cta:"Open the word card",title:"In a sentence · heuristic",body:"The teacher gave students a heuristic for estimating answers — always round to the nearest ten before calculating — to help them catch big mistakes.",clip:1},"wh-heuristic":{src:"concept:109:words:4:hook",route:"#/word/heuristic",cta:"Open the word card",title:"Remember it · heuristic",body:"HEURistic — Eureka! It shares roots with the word EUREKA (I found it!)."},"wo-heuristic":{src:"lore:heuristic:0",route:"#/word/heuristic",cta:"Open the word card",title:"Where it comes from · heuristic",body:"Greek heuriskein = to find/discover"},"wd-nescient":{src:"concept:109:words:7:def",route:"#/word/nescient",cta:"Open the word card",title:"nescient",roman:"NESH-ee-ent",body:"holding that only material phenomena can be known and knowledge of spiritual matters or ultimate causes is impossible",clip:1},"wx-nescient":{src:"concept:109:words:7:ex",route:"#/word/nescient",cta:"Open the word card",title:"In a sentence · nescient",body:"The philosopher argued that a nescient person, unaware of spiritual truths beyond physical evidence, could still live a moral life guided entirely by reason and observable facts.",clip:1},"wh-nescient":{src:"concept:109:words:7:hook",route:"#/word/nescient",cta:"Open the word card",title:"Remember it · nescient",body:"NESCIENT sounds like 'not-science' — someone ignorant of what science knows."},"wd-ignoramus":{src:"concept:109:words:8:def",route:"#/word/ignoramus",cta:"Open the word card",title:"ignoramus",roman:"ih-gner-AY-muhs",body:"an ignorant person",clip:1},"wx-ignoramus":{src:"concept:109:words:8:ex",route:"#/word/ignoramus",cta:"Open the word card",title:"In a sentence · ignoramus",body:"The professor called his rude student an ignoramus for confidently declaring that the Earth was only a few thousand years old.",clip:1},"wh-ignoramus":{src:"concept:109:words:8:hook",route:"#/word/ignoramus",cta:"Open the word card",title:"Remember it · ignoramus",body:"An ignorAMUS is a real AMUS-ing dummy — no silent e, just a blunt Latin 'we do not know.'"},"wo-ignoramus":{src:"lore:ignoramus:0",route:"#/word/ignoramus",cta:"Open the word card",title:"Where it comes from · ignoramus",body:"Latin ignoramus = we do not know"},"wd-dissertation":{src:"concept:109:words:9:def",route:"#/word/dissertation",cta:"Open the word card",title:"dissertation",roman:"dih-ser-TAY-shuhn",body:"a treatise advancing a new point of view resulting from research; usually a requirement for an advanced academic degree",clip:1},"wx-dissertation":{src:"concept:109:words:9:ex",route:"#/word/dissertation",cta:"Open the word card",title:"In a sentence · dissertation",body:"After years of research, Maya finally submitted her dissertation on climate change to the university committee.",clip:1},"wh-dissertation":{src:"concept:109:words:9:hook",route:"#/word/dissertation",cta:"Open the word card",title:"Remember it · dissertation",body:"A disSERTation takes a SERT-ain topic apart — double 's' because you must work doubly hard to write one."},"wo-dissertation":{src:"lore:dissertation:0",route:"#/word/dissertation",cta:"Open the word card",title:"Where it comes from · dissertation",body:"Latin dissertare(to debate, discuss)"},"wd-exegesis":{src:"concept:109:words:10:def",route:"#/word/exegesis",cta:"Open the word card",title:"exegesis",roman:"ek-sih-JEE-sis",body:"an explanation or critical interpretation (especially of the Bible)",clip:1},"wx-exegesis":{src:"concept:109:words:10:ex",route:"#/word/exegesis",cta:"Open the word card",title:"In a sentence · exegesis",body:"Her careful exegesis of the parable revealed layers of meaning that most readers had overlooked.",clip:1},"wh-exegesis":{src:"concept:109:words:10:hook",route:"#/word/exegesis",cta:"Open the word card",title:"Remember it · exegesis",body:"EXEGESIS leads meaning OUT of text — spell it like it sounds: ex-e-GE-sis, no double letters."},"wo-exegesis":{src:"lore:exegesis:0",route:"#/word/exegesis",cta:"Open the word card",title:"Where it comes from · exegesis",body:"Greek exegeisthai = to lead out, interpret"},"wd-hermeneutics":{src:"concept:109:words:11:def",route:"#/word/hermeneutics",cta:"Open the word card",title:"hermeneutics",roman:"her-meh-NOO-tiks",body:"the branch of theology that deals with principles of exegesis",clip:1},"wx-hermeneutics":{src:"concept:109:words:11:ex",route:"#/word/hermeneutics",cta:"Open the word card",title:"In a sentence · hermeneutics",body:"Her course in hermeneutics taught her how to interpret ancient texts with both precision and imagination.",clip:1},"wh-hermeneutics":{src:"concept:109:words:11:hook",route:"#/word/hermeneutics",cta:"Open the word card",title:"Remember it · hermeneutics",body:"HERMES the messenger had to INTERPRET the gods' words — herMENEUtics is the art of interpretation."},"wo-hermeneutics":{src:"lore:hermeneutics:0",route:"#/word/hermeneutics",cta:"Open the word card",title:"Where it comes from · hermeneutics",body:"Greek hermeneutikos = of interpreting, from Hermes, divine messenger"},"wd-empirical":{src:"concept:109:words:14:def",route:"#/word/empirical",cta:"Open the word card",title:"empirical",roman:"eh-MPIH-rih-kuhl",body:"derived from experiment and observation rather than theory",clip:1},"wx-empirical":{src:"concept:109:words:14:ex",route:"#/word/empirical",cta:"Open the word card",title:"In a sentence · empirical",body:"The scientists gathered empirical evidence by conducting hundreds of experiments before publishing their findings.",clip:1},"wh-empirical":{src:"concept:109:words:14:hook",route:"#/word/empirical",cta:"Open the word card",title:"Remember it · empirical",body:"EMPIRIcal knowledge comes from EXPERIMENTS in the real world"},"wo-empirical":{src:"lore:empirical:0",route:"#/word/empirical",cta:"Open the word card",title:"Where it comes from · empirical",body:"Greek empeiria = experience, from empeiros = experienced"},"li-u107":{src:"concept:113:concept",route:"#/stop/u107",cta:"Open this stop",title:"Words About Movement & Direction",body:"Movement vocabulary draws from Latin roots cedere (go), venire (come), ferre (carry), and vertere (turn). Directional prefixes combine with these roots to create a precise vocabulary of motion."},"lc-u107-0":{src:"concept:113:cards:0",route:"#/stop/u107",cta:"Open this stop",title:"Words About Movement & Direction · cedere (go) compounds",body:"Precede = go before. Recede = go back. Concede = go together with = yield. Accede = go toward = agree. Secede (se- = apart) = go apart = formally withdraw from. Supersede = sit above = replace. Note: supersede ends in -sede (from sedere = sit), not -cede — the only common word that does."},"lc-u107-1":{src:"concept:113:cards:1",route:"#/stop/u107",cta:"Open this stop",title:"Words About Movement & Direction · venire (come) compounds",body:"Convene (con- + venire) = come together. Intervene = come between. Circumvent = come around = avoid or outwit. Prevent = come before = stop from happening. Adventure (ad- + ventura = thing about to come) = something coming toward you = an exciting event."},"lc-u107-2":{src:"concept:113:cards:2",route:"#/stop/u107",cta:"Open this stop",title:"Words About Movement & Direction · Walking Words",body:"Peripatetic = walking around = traveling from place to place. Perambulate (per- + ambulare = walk) = walk through. Itinerant (itinerare = to travel) = traveling from place to place. Ambulatory = able to walk. Somnambulist (somnus = sleep + ambulare) = a sleepwalker."},"lc-u107-3":{src:"concept:113:cards:3",route:"#/stop/u107",cta:"Open this stop",title:"Words About Movement & Direction · Directional Prefixes Review",body:"Every movement word has a directional prefix + a movement root: pre- (before) + cedere = precede. re- (back) + cedere = recede. con- (together) + venire = convene. inter- (between) + venire = intervene. Knowing the prefix + knowing the root = knowing the word."},"lc-u107-4":{src:"concept:113:cards:4",route:"#/stop/u107",cta:"Open this stop",title:"Words About Movement & Direction · Spelling Movement Words",body:"Peripatetic = P-E-R-I-P-A-T-E-T-I-C. Perambulate = P-E-R-A-M-B-U-L-A-T-E. Somnambulist = S-O-M-N-A-M-B-U-L-I-S-T. Circumvent = C-I-R-C-U-M-V-E-N-T. Supersede = S-U-P-E-R-S-E-D-E (-sede not -cede). Movement words spell correctly when you know the root and count the prefix."},"uq-u107-0":{src:"unit:u107:qs:0",route:"#/stop/u107",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Words About Movement & Direction”?",opts:["Movement vocabulary draws from Latin roots cedere (go), venire (come), ferre (carry), and vertere (turn).","Contronyms (also called autoantonyms) are words with two opposite meanings.","Latin re- = again or back.","Latin trans- = across, beyond, or through complete change."],after:"From “Words About Movement & Direction”."}},"uq-u107-3":{src:"unit:u107:qs:3",route:"#/stop/u107",cta:"Open this stop",title:"Whose hook?",play:{q:"“A ▁▁▁ person PATters their feet walking around — peri (around) + PAT (walk) + etic.” — which word is this hook about?",opts:["peripatetic","perambulate","itinerant","somnambulist"],after:"From “Words About Movement & Direction”."}},"wd-perambulate":{src:"concept:113:words:1:def",route:"#/word/perambulate",cta:"Open the word card",title:"perambulate",roman:"per-AM-byoo-layt",body:"make an official inspection on foot of (the bounds of a property)",clip:1},"wx-perambulate":{src:"concept:113:words:1:ex",route:"#/word/perambulate",cta:"Open the word card",title:"In a sentence · perambulate",body:"Selectmen are required by law to perambulate the bounds every five years",clip:1},"wh-perambulate":{src:"concept:113:words:1:hook",route:"#/word/perambulate",cta:"Open the word card",title:"Remember it · perambulate",body:"PER + AMBULATE — ambulance moves people; to perambulate is to walk all the way through an area."},"wo-perambulate":{src:"lore:perambulate:0",route:"#/word/perambulate",cta:"Open the word card",title:"Where it comes from · perambulate",body:"Latin: perambulo (Latin)"},"wd-itinerant":{src:"concept:113:words:2:def",route:"#/word/itinerant",cta:"Open the word card",title:"itinerant",roman:"eye-TIH-ner-uhnt",body:"a laborer who moves from place to place as demanded by employment",clip:1},"wx-itinerant":{src:"concept:113:words:2:ex",route:"#/word/itinerant",cta:"Open the word card",title:"In a sentence · itinerant",body:"The itinerant musician traveled from town to town throughout the summer, setting up his guitar case on busy street corners and playing folk songs for passersby in exchange for spare change.",clip:1},"wh-itinerant":{src:"concept:113:words:2:hook",route:"#/word/itinerant",cta:"Open the word card",title:"Remember it · itinerant",body:"An itinerANT is an ANT that wanders the road — remember the 'ant' at the end who keeps moving."},"wo-itinerant":{src:"lore:itinerant:0",route:"#/word/itinerant",cta:"Open the word card",title:"Where it comes from · itinerant",body:"Latin iter/itineris = journey, road"},"wd-recede":{src:"concept:113:words:5:def",route:"#/word/recede",cta:"Open the word card",title:"recede",roman:"r-ih-s-EE-d",body:"to move back or away to withdraw",clip:1},"wx-recede":{src:"concept:113:words:5:ex",route:"#/word/recede",cta:"Open the word card",title:"In a sentence · recede",body:"After three days of heavy rainfall, the townspeople anxiously watched the floodwaters finally begin to recede, slowly pulling back from the streets and leaving a thick layer of mud behind.",clip:1},"wh-recede":{src:"concept:113:words:5:hook",route:"#/word/recede",cta:"Open the word card",title:"Remember it · recede",body:"When waters RECEDE, they go back — re-(back) + CEDE (give way), ending neatly in E-D-E like 'concede.'"},"wo-recede":{src:"lore:recede:0",route:"#/word/recede",cta:"Open the word card",title:"Where it comes from · recede",body:"Latin recedere = to go back, re- = back + cedere = to go"},"wd-concede":{src:"concept:113:words:6:def",route:"#/word/concede",cta:"Open the word card",title:"concede",roman:"kuh-NSEED",body:"admit (to a wrongdoing)",clip:1},"wx-concede":{src:"concept:113:words:6:ex",route:"#/word/concede",cta:"Open the word card",title:"In a sentence · concede",body:"I had to concede that I had left the gate open and the goats escaped.",clip:1},"wh-concede":{src:"concept:113:words:6:hook",route:"#/word/concede",cta:"Open the word card",title:"Remember it · concede",body:"To conCEDE is to let others proCEED — both share -CEDE meaning to go or yield."},"wo-concede":{src:"lore:concede:0",route:"#/word/concede",cta:"Open the word card",title:"Where it comes from · concede",body:"Latin 'concedere' (to yield), from con- + cedere (to go, yield)."},"wd-accede":{src:"concept:113:words:7:def",route:"#/word/accede",cta:"Open the word card",title:"accede",roman:"a-KSEED",body:"yield to another's wish or opinion",clip:1},"wx-accede":{src:"concept:113:words:7:ex",route:"#/word/accede",cta:"Open the word card",title:"In a sentence · accede",body:"Dad agreed to accede to our pleas and let us camp in the back garden.",clip:1},"wh-accede":{src:"concept:113:words:7:hook",route:"#/word/accede",cta:"Open the word card",title:"Remember it · accede",body:"To accEDE, you yield like a ceding nation — double 'c', then end with 'ede' like 'cede'."},"wd-secede":{src:"concept:113:words:8:def",route:"#/word/secede",cta:"Open the word card",title:"secede",roman:"s-ih-s-EE-d",body:"to withdraw formally from an alliance",clip:1},"wx-secede":{src:"concept:113:words:8:ex",route:"#/word/secede",cta:"Open the word card",title:"In a sentence · secede",body:"In 1861 several southern states voted to secede from the United States.",clip:1},"wh-secede":{src:"concept:113:words:8:hook",route:"#/word/secede",cta:"Open the word card",title:"Remember it · secede",body:"To seCEDE is to CEDE yourself apart—the South ceded to secede."},"wo-secede":{src:"lore:secede:0",route:"#/word/secede",cta:"Open the word card",title:"Where it comes from · secede",body:"Latin secedere = se-(apart)+cedere(to go)"},"wd-convene":{src:"concept:113:words:10:def",route:"#/word/convene",cta:"Open the word card",title:"convene",roman:"kuh-NVEEN",body:"meet formally",clip:1},"wx-convene":{src:"concept:113:words:10:ex",route:"#/word/convene",cta:"Open the word card",title:"In a sentence · convene",body:"The council convened last week",clip:1},"wh-convene":{src:"concept:113:words:10:hook",route:"#/word/convene",cta:"Open the word card",title:"Remember it · convene",body:"To conVENE is to COME together — VENue is where people convene."},"wd-intervene":{src:"concept:113:words:11:def",route:"#/word/intervene",cta:"Open the word card",title:"intervene",roman:"ih-nter-VEEN",body:"get involved, so as to alter or hinder an action, or through force or threat of force",clip:1},"wx-intervene":{src:"concept:113:words:11:ex",route:"#/word/intervene",cta:"Open the word card",title:"In a sentence · intervene",body:"Why did the U.S. not intervene earlier in WW II?",clip:1},"wh-intervene":{src:"concept:113:words:11:hook",route:"#/word/intervene",cta:"Open the word card",title:"Remember it · intervene",body:"InterVENE: someone who interVENEs COMES BETWEEN — the VEIN of a rescuer runs between two fighters."},"wo-intervene":{src:"lore:intervene:0",route:"#/word/intervene",cta:"Open the word card",title:"Where it comes from · intervene",body:"Latin intervenire = to come between, from inter+venire = to come"},"wd-circumvent":{src:"concept:113:words:12:def",route:"#/word/circumvent",cta:"Open the word card",title:"circumvent",roman:"sur-kuh-MVEHNT",body:"to find a way around a rule, problem, or obstacle",clip:1},"wx-circumvent":{src:"concept:113:words:12:ex",route:"#/word/circumvent",cta:"Open the word card",title:"In a sentence · circumvent",body:"Ants circumvent the puddle by marching in a long curve around its muddy edge.",clip:1},"wh-circumvent":{src:"concept:113:words:12:hook",route:"#/word/circumvent",cta:"Open the word card",title:"Remember it · circumvent",body:"CircumVENT — you VENT air around an obstacle to bypass it — VENT is the way out."},"wo-circumvent":{src:"lore:circumvent:0",route:"#/word/circumvent",cta:"Open the word card",title:"Where it comes from · circumvent",body:"Latin circumvenire = to come around"},"wd-prevent":{src:"concept:113:words:13:def",route:"#/word/prevent",cta:"Open the word card",title:"prevent",roman:"prih-VEHNT",body:"keep from happening or arising; make impossible",clip:1},"wx-prevent":{src:"concept:113:words:13:ex",route:"#/word/prevent",cta:"Open the word card",title:"In a sentence · prevent",body:"Sandbags along the riverbank prevent floodwater from reaching the village houses.",clip:1},"wh-prevent":{src:"concept:113:words:13:hook",route:"#/word/prevent",cta:"Open the word card",title:"Remember it · prevent",body:"To preVENT is to COME before the event and stop it — pre + VENT (air comes out before the fire starts)."},"wd-ambulatory":{src:"concept:113:words:14:def",route:"#/word/ambulatory",cta:"Open the word card",title:"ambulatory",roman:"A-mbyuh-luh-taw-ree",body:"a covered walkway (as in a cloister)",clip:1},"wx-ambulatory":{src:"concept:113:words:14:ex",route:"#/word/ambulatory",cta:"Open the word card",title:"In a sentence · ambulatory",body:"it has an ambulatory and seven chapels",clip:1},"wh-ambulatory":{src:"concept:113:words:14:hook",route:"#/word/ambulatory",cta:"Open the word card",title:"Remember it · ambulatory",body:"An AMBULATORY is a walking corridor — remember AMBULate + -ORY (like a dormitory, a place for doing something)."},"wo-ambulatory":{src:"lore:ambulatory:0",route:"#/word/ambulatory",cta:"Open the word card",title:"Where it comes from · ambulatory",body:"Latin ambulatorius = relating to walking"},"li-u108":{src:"concept:114:concept",route:"#/stop/u108",cta:"Open this stop",title:"Literary & Poetic Devices",body:"Literary vocabulary describes the tools of writers and poets. These Greek and Latin terms appear in both vocabulary rounds and are the kind of advanced knowledge that separates competition levels."},"lc-u108-0":{src:"concept:114:cards:0",route:"#/stop/u108",cta:"Open this stop",title:"Literary & Poetic Devices · Sound Devices",body:"Alliteration (al- + litera = letter) = repeated initial consonant sounds. Assonance (assonare = to correspond in sound) = repeated vowel sounds. Onomatopoeia = words that sound like what they mean. Cacophony = harsh discordant sounds. Euphony = pleasant harmonious sounds."},"lc-u108-1":{src:"concept:114:cards:1",route:"#/stop/u108",cta:"Open this stop",title:"Literary & Poetic Devices · Imagery Devices",body:'Metaphor (meta- + pherein = carry) = a comparison without like or as. Simile (similis = like) = a comparison using like or as. Synecdoche (synekdoche = taking up together) = a part representing the whole ("wheels" for a car).'},"lc-u108-2":{src:"concept:114:cards:2",route:"#/stop/u108",cta:"Open this stop",title:"Literary & Poetic Devices · Structure Devices",body:"Chiasmus = ABBA inversion structure. Anaphora = repetition at the start. Epistrophe = repetition at the end. Anadiplosis (ana- = back + diplous = double) = ending one clause with a word, starting the next with it. Symploce (symploce = interweaving) = combining anaphora and epistrophe."},"lc-u108-3":{src:"concept:114:cards:3",route:"#/stop/u108",cta:"Open this stop",title:"Literary & Poetic Devices · Rare Literary Terms",body:'Syzygy (syzygos = yoked) = in poetry, two feet joined together; in astronomy, three bodies aligned. S-Y-Z-Y-G-Y = six letters, three of which are y (all vowels). Tmesis (tmesis = cutting) = inserting a word inside another: "what-SO-ever."'},"lc-u108-4":{src:"concept:114:cards:4",route:"#/stop/u108",cta:"Open this stop",title:"Literary & Poetic Devices · Spelling Literary Terms",body:"Syzygy = S-Y-Z-Y-G-Y (three y's as vowels — a Greek vowel festival!). Synecdoche = S-Y-N-E-C-D-O-C-H-E (-ch- = /k/ Greek). Metonymy = M-E-T-O-N-Y-M-Y (-nym- from onoma = name). Anadiplosis = A-N-A-D-I-P-L-O-S-I-S. Chiasmus = C-H-I-A-S-M-U-S. Literary terms all follow Greek spelling rules."},"uq-u108-0":{src:"unit:u108:qs:0",route:"#/stop/u108",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Literary & Poetic Devices”?",opts:["Literary vocabulary describes the tools of writers and poets.","Contronyms (also called autoantonyms) are words with two opposite meanings.","Latin re- = again or back.","Latin trans- = across, beyond, or through complete change."],after:"From “Literary & Poetic Devices”."}},"uq-u108-3":{src:"unit:u108:qs:3",route:"#/stop/u108",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁: no vowels except Y—three bodies lined up like three Y's” — which word is this hook about?",opts:["syzygy","synecdoche","metonymy","chiasmus"],after:"From “Literary & Poetic Devices”."}},"wd-syzygy":{src:"concept:114:words:0:def",route:"#/word/syzygy",cta:"Open the word card",title:"syzygy",roman:"SIZ-ih-jee",body:"the straight line configuration of 3 celestial bodies (as the sun and earth and moon) in a gravitational system",clip:1},"wx-syzygy":{src:"concept:114:words:0:ex",route:"#/word/syzygy",cta:"Open the word card",title:"In a sentence · syzygy",body:"During a total solar eclipse, the sun, moon, and earth achieve a perfect syzygy that briefly turns day into night.",clip:1},"wh-syzygy":{src:"concept:114:words:0:hook",route:"#/word/syzygy",cta:"Open the word card",title:"Remember it · syzygy",body:"SYZYGY: no vowels except Y—three bodies lined up like three Y's"},"wo-syzygy":{src:"lore:syzygy:0",route:"#/word/syzygy",cta:"Open the word card",title:"Where it comes from · syzygy",body:"Greek suzugia = yoked together, from syn-(together) + zugon(yoke)"},"wd-synecdoche":{src:"concept:114:words:1:def",route:"#/word/synecdoche",cta:"Open the word card",title:"synecdoche",roman:"sih-NEK-duh-kee",body:"substituting a more inclusive term for a less inclusive one or vice versa",clip:1},"wx-synecdoche":{src:"concept:114:words:1:ex",route:"#/word/synecdoche",cta:"Open the word card",title:"In a sentence · synecdoche",body:"When the coach shouted 'All hands on deck!' she used a synecdoche, referring to the whole team by just one body part.",clip:1},"wh-synecdoche":{src:"concept:114:words:1:hook",route:"#/word/synecdoche",cta:"Open the word card",title:"Remember it · synecdoche",body:"synECDoche — ECD sounds like 'a piece' standing for the whole"},"wo-synecdoche":{src:"lore:synecdoche:0",route:"#/word/synecdoche",cta:"Open the word card",title:"Where it comes from · synecdoche",body:"Greek synekdoche = taking up together (syn = together + ekdoche = interpretation)"},"wd-metonymy":{src:"concept:114:words:2:def",route:"#/word/metonymy",cta:"Open the word card",title:"metonymy",roman:"meh-TON-uh-mee",body:"substituting the name of an attribute or feature for the name of the thing itself (as in ‘they counted heads’)",clip:1},"wx-metonymy":{src:"concept:114:words:2:ex",route:"#/word/metonymy",cta:"Open the word card",title:"In a sentence · metonymy",body:"The poet used metonymy when he wrote 'the crown decided' to mean the king decided.",clip:1},"wh-metonymy":{src:"concept:114:words:2:hook",route:"#/word/metonymy",cta:"Open the word card",title:"Remember it · metonymy",body:"metoNYMY — the NY in the middle is like New York called 'the Crown' — a perfect metonymy hiding in the spelling."},"wo-metonymy":{src:"lore:metonymy:0",route:"#/word/metonymy",cta:"Open the word card",title:"Where it comes from · metonymy",body:"Greek metonymia = change of name (meta = change + onoma = name)"},"wd-chiasmus":{src:"concept:114:words:3:def",route:"#/word/chiasmus",cta:"Open the word card",title:"chiasmus",roman:"ky-AZ-mus",body:"inversion in the second of two parallel phrases",clip:1},"wx-chiasmus":{src:"concept:114:words:3:ex",route:"#/word/chiasmus",cta:"Open the word card",title:"In a sentence · chiasmus",body:"The famous line 'ask not what your country can do for you' is a classic example of chiasmus.",clip:1},"wh-chiasmus":{src:"concept:114:words:3:hook",route:"#/word/chiasmus",cta:"Open the word card",title:"Remember it · chiasmus",body:"'Ask not what chiasmus IS, but what IS chiasmus' — the word itself inverts, starting with 'chi' like an X."},"wo-chiasmus":{src:"lore:chiasmus:0",route:"#/word/chiasmus",cta:"Open the word card",title:"Where it comes from · chiasmus",body:"Greek khiasmos = inversion, from khiazein = to mark with X"},"wd-anaphora":{src:"concept:114:words:4:def",route:"#/word/anaphora",cta:"Open the word card",title:"anaphora",roman:"uh-NA-fer-uh",body:"using a pronoun or similar word instead of repeating a word used earlier",clip:1},"wx-anaphora":{src:"concept:114:words:4:ex",route:"#/word/anaphora",cta:"Open the word card",title:"In a sentence · anaphora",body:"The poet used anaphora brilliantly, beginning each stanza with the same powerful phrase to build emotion.",clip:1},"wh-anaphora":{src:"concept:114:words:4:hook",route:"#/word/anaphora",cta:"Open the word card",title:"Remember it · anaphora",body:"ANAPHORA carries a word back again — ana(again)+phora(carry) — like a rhetorical boomerang."},"wo-anaphora":{src:"lore:anaphora:0",route:"#/word/anaphora",cta:"Open the word card",title:"Where it comes from · anaphora",body:"Greek ana-(back/again)+pherein = to carry"},"wd-alliteration":{src:"concept:114:words:7:def",route:"#/word/alliteration",cta:"Open the word card",title:"alliteration",roman:"uh-LIH-ter-ay-shuhn",body:"use of the same consonant at the beginning of each stressed syllable in a line of verse",clip:1},"wx-alliteration":{src:"concept:114:words:7:ex",route:"#/word/alliteration",cta:"Open the word card",title:"In a sentence · alliteration",body:"Our poem used alliteration: silver snakes slithered silently through the swaying summer grass.",clip:1},"wh-alliteration":{src:"concept:114:words:7:hook",route:"#/word/alliteration",cta:"Open the word card",title:"Remember it · alliteration",body:"ALLITERATION: notice the double L and -LITER- inside — letters loving letters together!"},"wo-alliteration":{src:"lore:alliteration:0",route:"#/word/alliteration",cta:"Open the word card",title:"Where it comes from · alliteration",body:"Latin ad = to + littera = letter"},"wd-assonance":{src:"concept:114:words:8:def",route:"#/word/assonance",cta:"Open the word card",title:"assonance",roman:"AS-oh-nance",body:"the repetition of similar vowels in the stressed syllables of successive words",clip:1},"wx-assonance":{src:"concept:114:words:8:ex",route:"#/word/assonance",cta:"Open the word card",title:"In a sentence · assonance",body:"The poet used assonance brilliantly, repeating the long 'o' sound in 'slow golden glow.'",clip:1},"wh-assonance":{src:"concept:114:words:8:hook",route:"#/word/assonance",cta:"Open the word card",title:"Remember it · assonance",body:"ASSONANCE is about SOUND — find SON (sound) in the middle: as-SON-ance ends in -ANCE, not -ENCE."},"wo-assonance":{src:"lore:assonance:0",route:"#/word/assonance",cta:"Open the word card",title:"Where it comes from · assonance",body:"Latin assonare = to sound to (sonus = sound)"},"wd-onomatopoeia":{src:"concept:114:words:9:def",route:"#/word/onomatopoeia",cta:"Open the word card",title:"onomatopoeia",roman:"on-oh-mat-oh-PEE-uh",body:"using words that imitate the sound they denote",clip:1},"wx-onomatopoeia":{src:"concept:114:words:9:ex",route:"#/word/onomatopoeia",cta:"Open the word card",title:"In a sentence · onomatopoeia",body:"The poet used onomatopoeia brilliantly, filling the stanza with words like buzz, crash, and sizzle to bring the kitchen scene alive.",clip:1},"wh-onomatopoeia":{src:"concept:114:words:9:hook",route:"#/word/onomatopoeia",cta:"Open the word card",title:"Remember it · onomatopoeia",body:"ON-O-MAT-O-POE-IA — sounds like what it means, just like the device itself"},"wo-onomatopoeia":{src:"lore:onomatopoeia:0",route:"#/word/onomatopoeia",cta:"Open the word card",title:"Where it comes from · onomatopoeia",body:"Greek onoma = name + poiein = to make"},"wd-simile":{src:"concept:114:words:12:def",route:"#/word/simile",cta:"Open the word card",title:"simile",roman:"SIM-ih-lee",body:"a figure of speech in which two unlike things are compared",clip:1},"wx-simile":{src:"concept:114:words:12:ex",route:"#/word/simile",cta:"Open the word card",title:"In a sentence · simile",body:"The poet used a vivid simile, writing that her smile was like the first ray of morning sunlight.",clip:1},"wh-simile":{src:"concept:114:words:12:hook",route:"#/word/simile",cta:"Open the word card",title:"Remember it · simile",body:"A SIMILE ends in E — like a SMILE on the page when you compare two things cleverly."},"wo-simile":{src:"lore:simile:0",route:"#/word/simile",cta:"Open the word card",title:"Where it comes from · simile",body:"Latin similis = like, resembling"},"wd-tmesis":{src:"concept:114:words:13:def",route:"#/word/tmesis",cta:"Open the word card",title:"tmesis",roman:"TMEE-sis",body:"A rhetorical figure in which a word or phrase is split by the insertion of another word, often for emphasis or humorous effect, as in 'abso-blooming-lutely.'",clip:1},"wx-tmesis":{src:"concept:114:words:13:ex",route:"#/word/tmesis",cta:"Open the word card",title:"In a sentence · tmesis",body:"When Marcus said 'un-flipping-believable,' his English teacher recognized it as a perfect example of tmesis used for comic effect.",clip:1},"wh-tmesis":{src:"concept:114:words:13:hook",route:"#/word/tmesis",cta:"Open the word card",title:"Remember it · tmesis",body:"Tmesis CUTs a word in two—just as the 't' and 'm' are unusually cut together."},"wo-tmesis":{src:"lore:tmesis:0",route:"#/word/tmesis",cta:"Open the word card",title:"Where it comes from · tmesis",body:"Greek tmesis = cutting, from temnein = to cut"},"li-u109":{src:"concept:115:concept",route:"#/stop/u109",cta:"Open this stop",title:"Color, Light & Perception Words",body:"Color and light vocabulary comes from Latin lux/lucis (light), Greek khroma (color), and Old English for basic color terms. These words appear in science, art, and literature."},"lc-u109-0":{src:"concept:115:cards:0",route:"#/stop/u109",cta:"Open this stop",title:"Color, Light & Perception Words · Light Words",body:"Iridescent (iris = rainbow + -escent) = shimmering with rainbow colors. Luminescent (lumen = light + -escent) = emitting light not from heat. Incandescent (in- + candere = glow white) = glowing from high heat. Phosphorescent = glowing in the dark after absorbing light."},"lc-u109-1":{src:"concept:115:cards:1",route:"#/stop/u109",cta:"Open this stop",title:"Color, Light & Perception Words · Color Words",body:"Chromatic (khroma = color) = relating to color. Monochromatic = one color only. Polychromatic = many colors. Achromatic (a- + khroma) = without color = black, white, and grey only. Chiaroscuro = light and dark in art. Tenebrism (tenebra = darkness) = use of deep shadow in painting."},"lc-u109-2":{src:"concept:115:cards:2",route:"#/stop/u109",cta:"Open this stop",title:"Color, Light & Perception Words · Perception & Vision Words",body:"Diaphanous (dia- = through + phainein = show) = so thin as to allow light through = gossamer. Pellucid (per- + lucidus) = translucently clear. Opaque = no light passes through. Scintillating (scintilla = spark) = sparkling brilliantly. Resplendent (re- + splendere = shine) = shining brilliantly."},"lc-u109-3":{src:"concept:115:cards:3",route:"#/stop/u109",cta:"Open this stop",title:"Color, Light & Perception Words · Aurora Words",body:"Aurora (Latin goddess of dawn) = the northern/southern lights. Aurora borealis (borealis = northern) = northern lights. Aurora australis (australis = southern) = southern lights. Crepuscular (crepusculum = twilight) = relating to twilight. Diurnal vs nocturnal = day vs night."},"lc-u109-4":{src:"concept:115:cards:4",route:"#/stop/u109",cta:"Open this stop",title:"Color, Light & Perception Words · Spelling Light Words",body:"Iridescent = I-R-I-D-E-S-C-E-N-T (-sc- before e = /s/). Luminescent = L-U-M-I-N-E-S-C-E-N-T. Incandescent = I-N-C-A-N-D-E-S-C-E-N-T. Phosphorescent = P-H-O-S-P-H-O-R-E-S-C-E-N-T (two -ph- Greek signals!). Diaphanous = D-I-A-P-H-A-N-O-U-S. Pellucid = P-E-L-L-U-C-I-D (double-l)."},"uq-u109-0":{src:"unit:u109:qs:0",route:"#/stop/u109",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Color, Light & Perception Words”?",opts:["Color and light vocabulary comes from Latin lux/lucis (light), Greek khroma (color), and Old English for basic color terms.","Contronyms (also called autoantonyms) are words with two opposite meanings.","Latin re- = again or back.","Latin trans- = across, beyond, or through complete change."],after:"From “Color, Light & Perception Words”."}},"wd-phosphorescent":{src:"concept:115:words:3:def",route:"#/word/phosphorescent",cta:"Open the word card",title:"phosphorescent",roman:"fos-fuh-RES-unt",body:"emitting light without appreciable heat as by slow oxidation of phosphorous",clip:1},"wx-phosphorescent":{src:"concept:115:words:3:ex",route:"#/word/phosphorescent",cta:"Open the word card",title:"In a sentence · phosphorescent",body:"The phosphorescent jellyfish drifted silently through the dark ocean water, glowing an eerie blue-green that lit up the waves around them.",clip:1},"wh-phosphorescent":{src:"concept:115:words:3:hook",route:"#/word/phosphorescent",cta:"Open the word card",title:"Remember it · phosphorescent",body:"PHOSPHORUS + ESCENT: like PHOSPHORUS glowing in the dark"},"wo-phosphorescent":{src:"lore:phosphorescent:0",route:"#/word/phosphorescent",cta:"Open the word card",title:"Where it comes from · phosphorescent",body:"Greek phosphoros = light-bearing (phos = light + phoros = carrying)"},"wx-pellucid":{src:"concept:115:words:7:ex",route:"#/word/pellucid",cta:"Open the word card",title:"In a sentence · pellucid",body:"The pellucid water of the mountain spring revealed every pebble glinting on the streambed below.",clip:1},"wh-pellucid":{src:"concept:115:words:7:hook",route:"#/word/pellucid",cta:"Open the word card",title:"Remember it · pellucid",body:"PELLUCID has LUCID inside it — double 'l' then LUCID, because clear light shines through LUCIDLY."},"wd-resplendent":{src:"concept:115:words:9:def",route:"#/word/resplendent",cta:"Open the word card",title:"resplendent",roman:"ree-SPLEH-nduhnt",body:"having great beauty and splendor",clip:1},"wx-resplendent":{src:"concept:115:words:9:ex",route:"#/word/resplendent",cta:"Open the word card",title:"In a sentence · resplendent",body:"Resplendent in the morning sunshine, the peacock spread its tail like a painted fan.",clip:1},"wh-resplendent":{src:"concept:115:words:9:hook",route:"#/word/resplendent",cta:"Open the word card",title:"Remember it · resplendent",body:"resPLENDent — PLEND sounds like SPLENDID; it's so shiny it nearly spells splendid inside."},"wo-resplendent":{src:"lore:resplendent:0",route:"#/word/resplendent",cta:"Open the word card",title:"Where it comes from · resplendent",body:"Latin resplendere = to shine brightly"},"wd-chromatic":{src:"concept:115:words:10:def",route:"#/word/chromatic",cta:"Open the word card",title:"chromatic",roman:"kroh-MAT-ik",body:"able to refract light without spectral color separation",clip:1},"wx-chromatic":{src:"concept:115:words:10:ex",route:"#/word/chromatic",cta:"Open the word card",title:"In a sentence · chromatic",body:"The music teacher introduced the chromatic scale to her students, explaining that it includes every half step between notes and covers the full range of pitches.",clip:1},"wh-chromatic":{src:"concept:115:words:10:hook",route:"#/word/chromatic",cta:"Open the word card",title:"Remember it · chromatic",body:"CHROMATIC scales have all the colors of sound—CHROMA + TIC, the clock TICs through every hue."},"wo-chromatic":{src:"lore:chromatic:0",route:"#/word/chromatic",cta:"Open the word card",title:"Where it comes from · chromatic",body:"Greek khromatikos = relating to color"},"wd-achromatic":{src:"concept:115:words:12:def",route:"#/word/achromatic",cta:"Open the word card",title:"achromatic",roman:"ay-kroh-MAT-ik",body:"having no hue",clip:1},"wx-achromatic":{src:"concept:115:words:12:ex",route:"#/word/achromatic",cta:"Open the word card",title:"In a sentence · achromatic",body:"The photographer converted the colorful image into an achromatic print, leaving only shades of gray from pure white to deep black.",clip:1},"wh-achromatic":{src:"concept:115:words:12:hook",route:"#/word/achromatic",cta:"Open the word card",title:"Remember it · achromatic",body:"Achromatic = a (without) + chromatic (color) — like a black-and-white TV without any chroma."},"wo-achromatic":{src:"lore:achromatic:0",route:"#/word/achromatic",cta:"Open the word card",title:"Where it comes from · achromatic",body:"Greek a- = without + khroma = color"},"wd-crepuscular":{src:"concept:115:words:14:def",route:"#/word/crepuscular",cta:"Open the word card",title:"crepuscular",roman:"krih-PUS-kyoo-ler",body:"like twilight; dim",clip:1},"wx-crepuscular":{src:"concept:115:words:14:ex",route:"#/word/crepuscular",cta:"Open the word card",title:"In a sentence · crepuscular",body:"Deer are crepuscular animals, so hikers are most likely to spot them just after sunrise or right before sunset.",clip:1},"wh-crepuscular":{src:"concept:115:words:14:hook",route:"#/word/crepuscular",cta:"Open the word card",title:"Remember it · crepuscular",body:"CREPUSCular creatures CREEP out at dusk"},"wo-crepuscular":{src:"lore:crepuscular:0",route:"#/word/crepuscular",cta:"Open the word card",title:"Where it comes from · crepuscular",body:"Latin crepusculum = twilight (from creper = dark, obscure)"},"wd-vespertine":{src:"concept:115:words:15:def",route:"#/word/vespertine",cta:"Open the word card",title:"vespertine",roman:"VES-per-tyn",body:"of, relating to, or occurring in the evening; used in biology to describe animals or plants that are most active or open during the evening hours",clip:1},"wx-vespertine":{src:"concept:115:words:15:ex",route:"#/word/vespertine",cta:"Open the word card",title:"In a sentence · vespertine",body:"The vespertine chorus of crickets and frogs began each evening just as the sun dipped below the horizon.",clip:1},"wh-vespertine":{src:"concept:115:words:15:hook",route:"#/word/vespertine",cta:"Open the word card",title:"Remember it · vespertine",body:"VESPER-tine: vespers are evening prayers, so vespertine means 'of the evening' — the -tine ending is fine, like 'fine' evenings."},"wo-vespertine":{src:"lore:vespertine:0",route:"#/word/vespertine",cta:"Open the word card",title:"Where it comes from · vespertine",body:"Latin vesper = evening"},"li-u110":{src:"concept:116:concept",route:"#/stop/u110",cta:"Open this stop",title:"Sound, Music & Language Theory",body:"Advanced sound and language vocabulary from Greek linguistics and music theory. These terms appear in championship rounds and are built from well-known Greek roots in new combinations."},"lc-u110-0":{src:"concept:116:cards:0",route:"#/stop/u110",cta:"Open this stop",title:"Sound, Music & Language Theory · Sweet Sound Words",body:"Mellifluous (mel = honey + fluere = flow) = sweetly smooth sounding. Dulcet (dulcis = sweet) = sweet and soothing. Sonorous (sonorus = resonant) = deep and rich in sound. Resonant = reinforced or prolonged by vibration. Euphonious = pleasant in sound."},"lc-u110-1":{src:"concept:116:cards:1",route:"#/stop/u110",cta:"Open this stop",title:"Sound, Music & Language Theory · Harsh Sound Words",body:"Cacophonous = harsh and discordant. Strident (stridere = to creak) = loud and harsh. Raucous (raucus = hoarse) = harsh and loud. Discordant = without harmony. Dissonant = clashing in sound. Grating = irritatingly harsh. Stentorian (from Stentor, a Greek herald with a huge voice) = very loud."},"lc-u110-2":{src:"concept:116:cards:2",route:"#/stop/u110",cta:"Open this stop",title:"Sound, Music & Language Theory · Language Theory Words",body:"Polysemy (poly- + sema = meaning) = a word having multiple meanings. Homophony = same sound. Synonymy = same meaning. Antonymy = opposite meaning. Pragmatics (pragma = action) = how context affects meaning. Semantics (sema = sign) = the study of meaning. Morphology = the study of word forms."},"lc-u110-3":{src:"concept:116:cards:3",route:"#/stop/u110",cta:"Open this stop",title:"Sound, Music & Language Theory · Poetry Sound Terms",body:"Sibilance = repeated /s/ sounds. Assonance = repeated vowel sounds. Consonance = repeated consonant sounds. Enjambment (enjamber = to stride over) = a line of poetry that continues without pause into the next. Caesura (caedere = to cut) = a pause within a line of verse."},"lc-u110-4":{src:"concept:116:cards:4",route:"#/stop/u110",cta:"Open this stop",title:"Sound, Music & Language Theory · Spelling Sound Words",body:"Mellifluous = M-E-L-L-I-F-L-U-O-U-S (double-l). Dulcet = D-U-L-C-E-T. Sonorous = S-O-N-O-R-O-U-S. Stentorian = S-T-E-N-T-O-R-I-A-N. Polysemy = P-O-L-Y-S-E-M-Y (y as Greek vowel). Enjambment = E-N-J-A-M-B-M-E-N-T (mb cluster). Caesura = C-A-E-S-U-R-A (ae diphthong)."},"uq-u110-0":{src:"unit:u110:qs:0",route:"#/stop/u110",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Sound, Music & Language Theory”?",opts:["Advanced sound and language vocabulary from Greek linguistics and music theory.","Contronyms (also called autoantonyms) are words with two opposite meanings.","Latin re- = again or back.","Latin trans- = across, beyond, or through complete change."],after:"From “Sound, Music & Language Theory”."}},"uq-u110-3":{src:"unit:u110:qs:3",route:"#/stop/u110",cta:"Open this stop",title:"Whose hook?",play:{q:"“MELLI-fluous sounds like MELLOW and flows like honey” — which word is this hook about?",opts:["mellifluous","dulcet","sonorous","resonant"],after:"From “Sound, Music & Language Theory”."}},"wd-mellifluous":{src:"concept:116:words:0:def",route:"#/word/mellifluous",cta:"Open the word card",title:"mellifluous",roman:"meh-LIF-loo-us",body:"sweetly or smoothly flowing",clip:1},"wx-mellifluous":{src:"concept:116:words:0:ex",route:"#/word/mellifluous",cta:"Open the word card",title:"In a sentence · mellifluous",body:"Her mellifluous singing drifted along the corridor and made everyone stop to listen.",clip:1},"wh-mellifluous":{src:"concept:116:words:0:hook",route:"#/word/mellifluous",cta:"Open the word card",title:"Remember it · mellifluous",body:"MELLI-fluous sounds like MELLOW and flows like honey"},"wo-mellifluous":{src:"lore:mellifluous:0",route:"#/word/mellifluous",cta:"Open the word card",title:"Where it comes from · mellifluous",body:"Latin mel = honey + fluere = to flow"},"wd-dulcet":{src:"concept:116:words:1:def",route:"#/word/dulcet",cta:"Open the word card",title:"dulcet",roman:"DUH-lsuht",body:"extremely pleasant in a gentle way",clip:1},"wx-dulcet":{src:"concept:116:words:1:ex",route:"#/word/dulcet",cta:"Open the word card",title:"In a sentence · dulcet",body:"the most dulcet swimming on the most beautiful and remote beaches",clip:1},"wh-dulcet":{src:"concept:116:words:1:hook",route:"#/word/dulcet",cta:"Open the word card",title:"Remember it · dulcet",body:"DULCET tones are sweetly DULC-et — think of the dulcimer, a sweet instrument sharing the same root."},"wd-sonorous":{src:"concept:116:words:2:def",route:"#/word/sonorous",cta:"Open the word card",title:"sonorous",roman:"SAH-ner-uhs",body:"full and loud and deep",clip:1},"wx-sonorous":{src:"concept:116:words:2:ex",route:"#/word/sonorous",cta:"Open the word card",title:"In a sentence · sonorous",body:"The orchestra's cellos filled the grand concert hall with a sonorous, resonant hum that vibrated in the listeners' chests and seemed to make the very walls tremble with its depth and beauty.",clip:1},"wh-sonorous":{src:"concept:116:words:2:hook",route:"#/word/sonorous",cta:"Open the word card",title:"Remember it · sonorous",body:"A SONOROUS voice is full of SONO-rous SOUND — the O's roll like deep bass notes."},"wo-sonorous":{src:"lore:sonorous:0",route:"#/word/sonorous",cta:"Open the word card",title:"Where it comes from · sonorous",body:"Latin sonorus = resonant, from sonus = sound"},"wd-resonant":{src:"concept:116:words:3:def",route:"#/word/resonant",cta:"Open the word card",title:"resonant",roman:"REH-zuh-nuhnt",body:"characterized by resonance",clip:1},"wx-resonant":{src:"concept:116:words:3:ex",route:"#/word/resonant",cta:"Open the word card",title:"In a sentence · resonant",body:"The speaker's resonant voice filled every corner of the enormous auditorium without a microphone, captivating the entire audience from the very first word.",clip:1},"wh-resonant":{src:"concept:116:words:3:hook",route:"#/word/resonant",cta:"Open the word card",title:"Remember it · resonant",body:"A reSON-ANT voice has a SON ringing through it — full and echoing."},"wo-resonant":{src:"lore:resonant:0",route:"#/word/resonant",cta:"Open the word card",title:"Where it comes from · resonant",body:"Latin resonare = to resound"},"wd-euphonious":{src:"concept:116:words:4:def",route:"#/word/euphonious",cta:"Open the word card",title:"euphonious",roman:"yoo-FOH-nee-us",body:"having a pleasant sound",clip:1},"wx-euphonious":{src:"concept:116:words:4:ex",route:"#/word/euphonious",cta:"Open the word card",title:"In a sentence · euphonious",body:"The euphonious melody drifting from the open window made every passerby slow their pace and smile.",clip:1},"wh-euphonious":{src:"concept:116:words:4:hook",route:"#/word/euphonious",cta:"Open the word card",title:"Remember it · euphonious",body:"EUPHONious — the EUPHON-y makes it sound good"},"wo-euphonious":{src:"lore:euphonious:0",route:"#/word/euphonious",cta:"Open the word card",title:"Where it comes from · euphonious",body:"Greek eu = well + phone = sound"},"wd-strident":{src:"concept:116:words:6:def",route:"#/word/strident",cta:"Open the word card",title:"strident",roman:"STREYE-duhnt",body:"conspicuously and offensively loud; given to vehement outcry",clip:1},"wx-strident":{src:"concept:116:words:6:ex",route:"#/word/strident",cta:"Open the word card",title:"In a sentence · strident",body:"The debate moderator asked the strident protestors outside to lower their voices, but their vehement chanting only grew louder as the vote approached.",clip:1},"wh-strident":{src:"concept:116:words:6:hook",route:"#/word/strident",cta:"Open the word card",title:"Remember it · strident",body:"STRIDENT ends in -ENT not -ANT — a strident voice is insistENT and urgENT."},"wd-raucous":{src:"concept:116:words:7:def",route:"#/word/raucous",cta:"Open the word card",title:"raucous",roman:"r-AW-k-uh-s",body:"harsh or strident",clip:1},"wx-raucous":{src:"concept:116:words:7:ex",route:"#/word/raucous",cta:"Open the word card",title:"In a sentence · raucous",body:"The raucous celebration that erupted in the gymnasium after the championship win was so loud that teachers two hallways away could clearly hear the cheering, stomping, and joyful screaming through the thick walls.",clip:1},"wh-raucous":{src:"concept:116:words:7:hook",route:"#/word/raucous",cta:"Open the word card",title:"Remember it · raucous",body:"RAW + COUS — a raucous noise sounds raw and rough."},"wo-raucous":{src:"lore:raucous:0",route:"#/word/raucous",cta:"Open the word card",title:"Where it comes from · raucous",body:"Latin raucus = hoarse, harsh-sounding"},"wo-stentorian":{src:"lore:stentorian:0",route:"#/word/stentorian",cta:"Open the word card",title:"Where it comes from · stentorian",body:"From Stentor, the Greek herald whose voice Homer said equalled fifty men"},"wd-polysemy":{src:"concept:116:words:9:def",route:"#/word/polysemy",cta:"Open the word card",title:"polysemy",roman:"puh-LIS-uh-mee",body:"the ambiguity of an individual word or phrase that can be used (in different contexts) to express two or more different meanings",clip:1},"wx-polysemy":{src:"concept:116:words:9:ex",route:"#/word/polysemy",cta:"Open the word card",title:"In a sentence · polysemy",body:"The word 'bank' is a perfect example of polysemy because it can mean a financial institution or the edge of a river.",clip:1},"wh-polysemy":{src:"concept:116:words:9:hook",route:"#/word/polysemy",cta:"Open the word card",title:"Remember it · polysemy",body:"Polysemy: poly means many, semy means meanings"},"wo-polysemy":{src:"lore:polysemy:0",route:"#/word/polysemy",cta:"Open the word card",title:"Where it comes from · polysemy",body:"Greek polys = many + sema = sign, meaning"},"wd-semantics":{src:"concept:116:words:10:def",route:"#/word/semantics",cta:"Open the word card",title:"semantics",roman:"sih-MA-ntihks",body:"the study of language meaning",clip:1},"wx-semantics":{src:"concept:116:words:10:ex",route:"#/word/semantics",cta:"Open the word card",title:"In a sentence · semantics",body:"a petty argument about semantics",clip:1},"wh-semantics":{src:"concept:116:words:10:hook",route:"#/word/semantics",cta:"Open the word card",title:"Remember it · semantics",body:"SEMANTICS — find the MANTIC inside, like a MANTRA of meaning — se-MANT-ics."},"wo-semantics":{src:"lore:semantics:0",route:"#/word/semantics",cta:"Open the word card",title:"Where it comes from · semantics",body:"Greek sema = sign + mantikos = of meaning"},"wd-enjambment":{src:"concept:116:words:14:def",route:"#/word/enjambment",cta:"Open the word card",title:"enjambment",roman:"en-JAM-ment",body:"the continuation of a syntactic unit from one line of verse into the next line without a pause",clip:1},"wx-enjambment":{src:"concept:116:words:14:ex",route:"#/word/enjambment",cta:"Open the word card",title:"In a sentence · enjambment",body:"The poet used enjambment so skillfully that readers were swept from one line to the next without pausing.",clip:1},"wh-enjambment":{src:"concept:116:words:14:hook",route:"#/word/enjambment",cta:"Open the word card",title:"Remember it · enjambment",body:"ENJAMBMENT has 'jamb' — like a door jamb, the line doesn't stop but keeps going through the frame."},"wd-caesura":{src:"concept:116:words:15:def",route:"#/word/caesura",cta:"Open the word card",title:"caesura",roman:"sih-ZHUR-uh",body:"a pause or interruption (as in a conversation)",clip:1},"wx-caesura":{src:"concept:116:words:15:ex",route:"#/word/caesura",cta:"Open the word card",title:"In a sentence · caesura",body:"after an ominous caesura the preacher continued",clip:1},"wh-caesura":{src:"concept:116:words:15:hook",route:"#/word/caesura",cta:"Open the word card",title:"Remember it · caesura",body:"A caesura CUTS a poetic line in two — the CAES comes from the Latin word for cutting."},"li-u111":{src:"concept:117:concept",route:"#/stop/u111",cta:"Open this stop",title:"Architecture & Urban Vocabulary",body:"Architecture vocabulary combines Latin, Greek, Italian, and French. Architectural terms describe both the physical elements of buildings and the philosophical concepts behind their design."},"lc-u111-0":{src:"concept:117:cards:0",route:"#/stop/u111",cta:"Open this stop",title:"Architecture & Urban Vocabulary · Structural Elements",body:"Buttress (Old French bouter = to push) = a structure supporting a wall. Colonnade (colonna = column) = a row of columns. Balustrade (balustre = a pillar) = a railing supported by small pillars. Crenellation (crena = notch) = the notched parapet of a castle."},"lc-u111-1":{src:"concept:117:cards:1",route:"#/stop/u111",cta:"Open this stop",title:"Architecture & Urban Vocabulary · Space & Form Words",body:"Fenestration (fenestra = window) = the arrangement of windows. Atrium (atrium = the main hall) = a central open space. Clerestory (cler- = clear + -story) = high windows above the main roof. Nave (navis = ship) = the central body of a church."},"lc-u111-2":{src:"concept:117:cards:2",route:"#/stop/u111",cta:"Open this stop",title:"Architecture & Urban Vocabulary · Classical Architecture",body:"Corinthian = the most ornate of the three Greek orders (with elaborate acanthus leaf capitals). Doric = the simplest order. Ionic = the middle order (with scroll capitals). Entablature = the horizontal structure above columns."},"lc-u111-3":{src:"concept:117:cards:3",route:"#/stop/u111",cta:"Open this stop",title:"Architecture & Urban Vocabulary · Urban Planning Words",body:"Agora (Greek) = a public gathering place. Forum (Latin) = a public square. Boulevard (French from German Bollwerk = bulwark) = a wide tree-lined road. Cul-de-sac (French = bottom of the sack) = a dead-end road. Esplanade (explanare = to flatten) = a long, flat open promenade."},"lc-u111-4":{src:"concept:117:cards:4",route:"#/stop/u111",cta:"Open this stop",title:"Architecture & Urban Vocabulary · Spelling Architecture Words",body:"Fenestration = F-E-N-E-S-T-R-A-T-I-O-N. Balustrade = B-A-L-U-S-T-R-A-D-E. Crenellation = C-R-E-N-E-L-L-A-T-I-O-N (double-l). Clerestory = C-L-E-R-E-S-T-O-R-Y. Entablature = E-N-T-A-B-L-A-T-U-R-E. Boulevard = B-O-U-L-E-V-A-R-D (-ou- French vowel)."},"uq-u111-3":{src:"unit:u111:qs:3",route:"#/stop/u111",cta:"Open this stop",title:"Whose hook?",play:{q:"“FENESTRA + TION — Latin fenestra means window; the -TION ending makes it the arrangement of windows.” — which word is this hook about?",opts:["fenestration","buttress","colonnade","balustrade"],after:"From “Architecture & Urban Vocabulary”."}},"wd-balustrade":{src:"concept:117:words:3:def",route:"#/word/balustrade",cta:"Open the word card",title:"balustrade",roman:"BAL-us-trayd",body:"a railing at the side of a staircase or balcony to prevent people from falling",clip:1},"wx-balustrade":{src:"concept:117:words:3:ex",route:"#/word/balustrade",cta:"Open the word card",title:"In a sentence · balustrade",body:"She gripped the marble balustrade tightly as she climbed the steep staircase inside the old palace.",clip:1},"wh-balustrade":{src:"concept:117:words:3:hook",route:"#/word/balustrade",cta:"Open the word card",title:"Remember it · balustrade",body:"BALUSTRADE: 'BALance USing a TRADE-mark railing' — the railing helps you balance; end it with -RADE like lemonade."},"wd-pediment":{src:"concept:117:words:5:def",route:"#/word/pediment",cta:"Open the word card",title:"pediment",roman:"PED-ih-ment",body:"a triangular gable between a horizontal entablature and a sloping roof",clip:1},"wx-pediment":{src:"concept:117:words:5:ex",route:"#/word/pediment",cta:"Open the word card",title:"In a sentence · pediment",body:"The ancient Greek temple's pediment was carved with scenes of gods battling giants.",clip:1},"wh-pediment":{src:"concept:117:words:5:hook",route:"#/word/pediment",cta:"Open the word card",title:"Remember it · pediment",body:"A pediMENT is the triMENTgular hat on top of a Greek temple — a pointy crown resting on stone feet."},"wd-atrium":{src:"concept:117:words:6:def",route:"#/word/atrium",cta:"Open the word card",title:"atrium",roman:"AY-t-r-ee-uh-m",body:"the central room of an ancient Roman house",clip:1},"wx-atrium":{src:"concept:117:words:6:ex",route:"#/word/atrium",cta:"Open the word card",title:"In a sentence · atrium",body:"Sunlight poured through the open roof of the Roman villa's atrium, filling the space with golden warmth.",clip:1},"wh-atrium":{src:"concept:117:words:6:hook",route:"#/word/atrium",cta:"Open the word card",title:"Remember it · atrium",body:"ATRIUM: the grand AT-RIUM entrance — keep the 'i' before 'u' and 'm', like a skylit Roman room: a-t-r-i-u-m."},"wo-atrium":{src:"lore:atrium:0",route:"#/word/atrium",cta:"Open the word card",title:"Where it comes from · atrium",body:"Latin atrium = central hall of a Roman house"},"wd-nave":{src:"concept:117:words:8:def",route:"#/word/nave",cta:"Open the word card",title:"nave",roman:"NAYV",body:"the central area of a church",clip:1},"wx-nave":{src:"concept:117:words:8:ex",route:"#/word/nave",cta:"Open the word card",title:"In a sentence · nave",body:"Rows of wooden pews lined the nave of the old cathedral, filling the long central aisle with quiet reverence.",clip:1},"wh-nave":{src:"concept:117:words:8:hook",route:"#/word/nave",cta:"Open the word card",title:"Remember it · nave",body:"The NAVE of a church looks like an upside-down ship — navis means ship in Latin."},"wd-apse":{src:"concept:117:words:9:def",route:"#/word/apse",cta:"Open the word card",title:"apse",roman:"APS",body:"a domed or vaulted recess or projection on a building especially the east end of a church; usually contains the altar",clip:1},"wx-apse":{src:"concept:117:words:9:ex",route:"#/word/apse",cta:"Open the word card",title:"In a sentence · apse",body:"The ancient cathedral's apse was decorated with glittering golden mosaics that caught the morning light.",clip:1},"wh-apse":{src:"concept:117:words:9:hook",route:"#/word/apse",cta:"Open the word card",title:"Remember it · apse",body:"An APSE is a curved niche — four letters curving like the arch itself: A-P-S-E."},"wd-corinthian":{src:"concept:117:words:10:def",route:"#/word/corinthian",cta:"Open the word card",title:"corinthian",roman:"ker-IH-nthee-uhn",body:"a man devoted to the pursuit of pleasure",clip:1},"wx-corinthian":{src:"concept:117:words:10:ex",route:"#/word/corinthian",cta:"Open the word card",title:"In a sentence · corinthian",body:"The temple featured tall Corinthian columns decorated with elaborate carvings of leaves at the top.",clip:1},"wh-corinthian":{src:"concept:117:words:10:hook",route:"#/word/corinthian",cta:"Open the word card",title:"Remember it · corinthian",body:"A CORINTHIAN loves luxury — the word ends in -IAN not -EAN, like a polished column capital."},"wo-corinthian":{src:"lore:corinthian:0",route:"#/word/corinthian",cta:"Open the word card",title:"Where it comes from · corinthian",body:"Greek Korinthos = city famous for luxury and vice"},"wd-doric":{src:"concept:117:words:11:def",route:"#/word/doric",cta:"Open the word card",title:"doric",roman:"DAW-rihk",body:"the dialect of Ancient Greek spoken in Doris",clip:1},"wx-doric":{src:"concept:117:words:11:ex",route:"#/word/doric",cta:"Open the word card",title:"In a sentence · doric",body:"The ruins featured thick columns built in the Doric style, sturdy and unadorned at the top.",clip:1},"wh-doric":{src:"concept:117:words:11:hook",route:"#/word/doric",cta:"Open the word card",title:"Remember it · doric",body:"DORIC columns are plain and simple — so is the spelling: just D-O-R-I-C, no fuss."},"wd-ionic":{src:"concept:117:words:12:def",route:"#/word/ionic",cta:"Open the word card",title:"ionic",roman:"eye-AH-nihk",body:"the dialect of Ancient Greek spoken and written in Attica and Athens and Ionia",clip:1},"wx-ionic":{src:"concept:117:words:12:ex",route:"#/word/ionic",cta:"Open the word card",title:"In a sentence · ionic",body:"The ancient ruins featured tall ionic columns with intricately carved capitals, reflecting the elegant architectural style developed in the Greek region of Ionia thousands of years ago.",clip:1},"wh-ionic":{src:"concept:117:words:12:hook",route:"#/word/ionic",cta:"Open the word card",title:"Remember it · ionic",body:"IONIC columns come from IONIA — end it with IC like 'classic,' a classic Greek style."},"wd-architrave":{src:"concept:117:words:14:def",route:"#/word/architrave",cta:"Open the word card",title:"architrave",roman:"AH-rkuh-trayv",body:"the molding around a door or window",clip:1},"wx-architrave":{src:"concept:117:words:14:ex",route:"#/word/architrave",cta:"Open the word card",title:"In a sentence · architrave",body:"The carpenter carefully carved an ornate architrave to frame the grand entrance of the Victorian mansion.",clip:1},"wh-architrave":{src:"concept:117:words:14:hook",route:"#/word/architrave",cta:"Open the word card",title:"Remember it · architrave",body:"An ARCHITRAVe is the CHIEF BEAM (trave) over a door — arch over, then TRAVE like 'travel' over the top."},"wd-agora":{src:"concept:117:words:15:def",route:"#/word/agora",cta:"Open the word card",title:"agora",roman:"A-ger-uh",body:"100 agorot equal 1 shekel in Israel",clip:1},"wx-agora":{src:"concept:117:words:15:ex",route:"#/word/agora",cta:"Open the word card",title:"In a sentence · agora",body:"In ancient Athens, citizens gathered in the agora to debate politics, trade goods, and share news.",clip:1},"wh-agora":{src:"concept:117:words:15:hook",route:"#/word/agora",cta:"Open the word card",title:"Remember it · agora",body:"The AGORA was where people gathered — one G, open like an open marketplace."},"wd-esplanade":{src:"concept:117:words:16:def",route:"#/word/esplanade",cta:"Open the word card",title:"esplanade",roman:"eh-spluh-NAHD",body:"a long stretch of open level ground (paved or grassy) for walking beside the seashore",clip:1},"wx-esplanade":{src:"concept:117:words:16:ex",route:"#/word/esplanade",cta:"Open the word card",title:"In a sentence · esplanade",body:"Families gathered along the esplanade on Sunday afternoons, strolling past ice cream vendors while watching the sailboats drift across the harbor.",clip:1},"wh-esplanade":{src:"concept:117:words:16:hook",route:"#/word/esplanade",cta:"Open the word card",title:"Remember it · esplanade",body:"An ESPLAnade is a PLAIN (flat) PROMENADE — flat ground for pleasant walking."},"wo-esplanade":{src:"lore:esplanade:0",route:"#/word/esplanade",cta:"Open the word card",title:"Where it comes from · esplanade",body:"French esplanade from Italian spianata = leveled ground (spianare = to level, from Latin planus = flat)"},"li-u112":{src:"concept:118:concept",route:"#/stop/u112",cta:"Open this stop",title:"The Natural World — Flora & Fauna Vocabulary",body:"Scientific names for plants and animals come from Latin and Greek, following the Linnaean classification system. These vocabulary words appear in science bee rounds and general championship vocabulary."},"lc-u112-0":{src:"concept:118:cards:0",route:"#/stop/u112",cta:"Open this stop",title:"The Natural World — Flora & Fauna Vocabulary · Tree & Plant Words",body:"Deciduous (de- + cadere = fall) = losing leaves annually. Coniferous (conus = cone + ferre = bear) = cone-bearing = evergreen. Arboreal (arbor = tree) = relating to trees or living in trees. Sylvan (silva = forest) = relating to forests. Herbaceous (herba = grass/herb) = a plant with no woody stem."},"lc-u112-1":{src:"concept:118:cards:1",route:"#/stop/u112",cta:"Open this stop",title:"The Natural World — Flora & Fauna Vocabulary · Animal Behavior",body:"Diurnal = active during the day. Nocturnal = active at night. Crepuscular = active at twilight. Migratory (migrare = to move) = moving seasonally. Hibernation (hibernare = to winter) = dormancy in winter. Estivation (aestivare = to spend summer) = dormancy in summer."},"lc-u112-2":{src:"concept:118:cards:2",route:"#/stop/u112",cta:"Open this stop",title:"The Natural World — Flora & Fauna Vocabulary · Classification Words",body:"Taxonomy (taxis = arrangement + nomos = law) = the science of classification. Phylogeny (phylon = tribe + genos) = evolutionary history. Morphology = study of form. Genus (genos) = a classification group. Species (specere = to look) = the fundamental classification unit."},"lc-u112-3":{src:"concept:118:cards:3",route:"#/stop/u112",cta:"Open this stop",title:"The Natural World — Flora & Fauna Vocabulary · Ecological Words",body:"Symbiosis (sym- + bios) = mutually beneficial relationship. Mutualism = both organisms benefit. Commensalism (com- + mensa = table) = one benefits, other is unaffected. Parasitism = one benefits, other is harmed. Predation (praedari = to plunder) = one organism killing another for food."},"lc-u112-4":{src:"concept:118:cards:4",route:"#/stop/u112",cta:"Open this stop",title:"The Natural World — Flora & Fauna Vocabulary · Spelling Nature Words",body:"Deciduous = D-E-C-I-D-U-O-U-S (-uous suffix). Coniferous = C-O-N-I-F-E-R-O-U-S. Arboreal = A-R-B-O-R-E-A-L. Herbaceous = H-E-R-B-A-C-E-O-U-S (-eous suffix). Taxonomy = T-A-X-O-N-O-M-Y. Phylogeny = P-H-Y-L-O-G-E-N-Y (ph = Greek; y = vowel twice)."},"uq-u112-0":{src:"unit:u112:qs:0",route:"#/stop/u112",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “The Natural World — Flora & Fauna Vocabulary”?",opts:["Scientific names for plants and animals come from Latin and Greek, following the Linnaean classification system.","Contronyms (also called autoantonyms) are words with two opposite meanings.","Latin re- = again or back.","Latin trans- = across, beyond, or through complete change."],after:"From “The Natural World — Flora & Fauna Vocabulary”."}},"uq-u112-3":{src:"unit:u112:qs:3",route:"#/stop/u112",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁ trees lose leaves — remember the U-O-U-S ending like the leaves falling: U-O-U-S, down, down, down.” — which word is this hook about?",opts:["deciduous","coniferous","arboreal","sylvan"],after:"From “The Natural World — Flora & Fauna Vocabulary”."}},"wd-deciduous":{src:"concept:118:words:0:def",route:"#/word/deciduous",cta:"Open the word card",title:"deciduous",roman:"dih-SIH-joo-uhs",body:"shedding foliage at the end of the growing season (of plants and shrubs)",clip:1},"wx-deciduous":{src:"concept:118:words:0:ex",route:"#/word/deciduous",cta:"Open the word card",title:"In a sentence · deciduous",body:"Every October, the deciduous trees lining our street put on a spectacular show of red, orange, and gold before dropping their leaves entirely and standing bare throughout the long winter months.",clip:1},"wh-deciduous":{src:"concept:118:words:0:hook",route:"#/word/deciduous",cta:"Open the word card",title:"Remember it · deciduous",body:"DecidUOUS trees lose leaves — remember the U-O-U-S ending like the leaves falling: U-O-U-S, down, down, down."},"wo-deciduous":{src:"lore:deciduous:0",route:"#/word/deciduous",cta:"Open the word card",title:"Where it comes from · deciduous",body:"Latin deciduus = falling off (de-+cadere=to fall)"},"wd-coniferous":{src:"concept:118:words:1:def",route:"#/word/coniferous",cta:"Open the word card",title:"coniferous",roman:"kuh-NIH-fer-uhs",body:"of or relating to or part of trees or shrubs bearing cones and evergreen leaves",clip:1},"wx-coniferous":{src:"concept:118:words:1:ex",route:"#/word/coniferous",cta:"Open the word card",title:"In a sentence · coniferous",body:"The hikers walked through a dense coniferous forest where towering pines blocked out most of the sunlight.",clip:1},"wh-coniferous":{src:"concept:118:words:1:hook",route:"#/word/coniferous",cta:"Open the word card",title:"Remember it · coniferous",body:"Coniferous trees are FAMOUS for their cones — remember 'coni-FER-ous' has FER in the middle, like itFERS (bears) cones."},"wo-coniferous":{src:"lore:coniferous:0",route:"#/word/coniferous",cta:"Open the word card",title:"Where it comes from · coniferous",body:"Latin conus = cone + ferre = to bear"},"wd-arboreal":{src:"concept:118:words:2:def",route:"#/word/arboreal",cta:"Open the word card",title:"arboreal",roman:"ah-RBAW-ree-uhl",body:"of or relating to or formed by trees",clip:1},"wx-arboreal":{src:"concept:118:words:2:ex",route:"#/word/arboreal",cta:"Open the word card",title:"In a sentence · arboreal",body:"The red-eyed tree frog is a remarkably arboreal creature, spending nearly its entire life clinging to leaves and branches high above the rain forest floor.",clip:1},"wh-arboreal":{src:"concept:118:words:2:hook",route:"#/word/arboreal",cta:"Open the word card",title:"Remember it · arboreal",body:"A squirrel is arborEAL — it EAts Acorns up in trees; spot E-A-L at the end."},"wo-arboreal":{src:"lore:arboreal:0",route:"#/word/arboreal",cta:"Open the word card",title:"Where it comes from · arboreal",body:"Latin arbor = tree + -alis = relating to"},"wd-sylvan":{src:"concept:118:words:3:def",route:"#/word/sylvan",cta:"Open the word card",title:"sylvan",roman:"SIH-lvuhn",body:"a spirit that lives in or frequents the woods",clip:1},"wx-sylvan":{src:"concept:118:words:3:ex",route:"#/word/sylvan",cta:"Open the word card",title:"In a sentence · sylvan",body:"a shady sylvan glade",clip:1},"wh-sylvan":{src:"concept:118:words:3:hook",route:"#/word/sylvan",cta:"Open the word card",title:"Remember it · sylvan",body:"SYLVan — think of Sylvester the cat hiding in SYLVan woods, spelled with a Y like 'mystery.'"},"wd-herbaceous":{src:"concept:118:words:4:def",route:"#/word/herbaceous",cta:"Open the word card",title:"herbaceous",roman:"er-BAY-shuhs",body:"characteristic of a nonwoody herb or plant part",clip:1},"wx-herbaceous":{src:"concept:118:words:4:ex",route:"#/word/herbaceous",cta:"Open the word card",title:"In a sentence · herbaceous",body:"The gardener pointed out that the herbaceous border along the fence needed to be cut back before the first frost.",clip:1},"wh-herbaceous":{src:"concept:118:words:4:hook",route:"#/word/herbaceous",cta:"Open the word card",title:"Remember it · herbaceous",body:"HERBaceous plants are full of HERBS — soft stems, not woody"},"wo-herbaceous":{src:"lore:herbaceous:0",route:"#/word/herbaceous",cta:"Open the word card",title:"Where it comes from · herbaceous",body:"Latin herba = grass, herb + aceus = adjective suffix meaning of the nature of"},"wd-hibernation":{src:"concept:118:words:8:def",route:"#/word/hibernation",cta:"Open the word card",title:"hibernation",roman:"heye-ber-NAY-shuhn",body:"the torpid or resting state in which some animals pass the winter",clip:1},"wx-hibernation":{src:"concept:118:words:8:ex",route:"#/word/hibernation",cta:"Open the word card",title:"In a sentence · hibernation",body:"he emerged from his hibernation to make his first appearance in several years",clip:1},"wh-hibernation":{src:"concept:118:words:8:hook",route:"#/word/hibernation",cta:"Open the word card",title:"Remember it · hibernation",body:"HibernATION — the bear's winter NATION of sleep; always starts with HI not HY, like hibernate."},"wo-hibernation":{src:"lore:hibernation:0",route:"#/word/hibernation",cta:"Open the word card",title:"Where it comes from · hibernation",body:"Latin hibernatio = a wintering, from hibernare = to winter"},"wd-taxonomy":{src:"concept:118:words:10:def",route:"#/word/taxonomy",cta:"Open the word card",title:"taxonomy",roman:"ta-KSAW-nuh-mee",body:"a classification of organisms into groups based on similarities of structure or origin etc",clip:1},"wx-taxonomy":{src:"concept:118:words:10:ex",route:"#/word/taxonomy",cta:"Open the word card",title:"In a sentence · taxonomy",body:"In biology class, we learned about the taxonomy that organizes all living things from kingdoms down to individual species.",clip:1},"wh-taxonomy":{src:"concept:118:words:10:hook",route:"#/word/taxonomy",cta:"Open the word card",title:"Remember it · taxonomy",body:"TAXONOMy: think TAX + GNOME + Y — the gnome who organizes all living things by law."},"wo-taxonomy":{src:"lore:taxonomy:0",route:"#/word/taxonomy",cta:"Open the word card",title:"Where it comes from · taxonomy",body:"Greek taxis = arrangement + nomos = law"},"wd-phylogeny":{src:"concept:118:words:11:def",route:"#/word/phylogeny",cta:"Open the word card",title:"phylogeny",roman:"feye-LAH-juh-nee",body:"in biology, the sequence of events involved in the evolutionary development of a species or taxonomic group of organisms",clip:1},"wx-phylogeny":{src:"concept:118:words:11:ex",route:"#/word/phylogeny",cta:"Open the word card",title:"In a sentence · phylogeny",body:"By studying phylogeny, scientists can trace how modern whales evolved from land-dwelling ancestors millions of years ago.",clip:1},"wh-phylogeny":{src:"concept:118:words:11:hook",route:"#/word/phylogeny",cta:"Open the word card",title:"Remember it · phylogeny",body:"PHYLOGENY traces your species' family tree — PHYLo + GENY, like PHYLosophically examining GENeration."},"wo-phylogeny":{src:"lore:phylogeny:0",route:"#/word/phylogeny",cta:"Open the word card",title:"Where it comes from · phylogeny",body:"Greek phylon = race + genesis = origin"},"wx-mutualism":{src:"concept:118:words:13:ex",route:"#/word/mutualism",cta:"Open the word card",title:"In a sentence · mutualism",body:"The relationship between clownfish and sea anemones is a classic example of mutualism, where both species benefit.",clip:1},"wh-mutualism":{src:"concept:118:words:13:hook",route:"#/word/mutualism",cta:"Open the word card",title:"Remember it · mutualism",body:"Mutualism ends in -ism because it's a system where both sides benefit — remember i-s-m not i-z-m."},"wo-mutualism":{src:"lore:mutualism:0",route:"#/word/mutualism",cta:"Open the word card",title:"Where it comes from · mutualism",body:"Latin mutuus = reciprocal"},"wd-commensalism":{src:"concept:118:words:14:def",route:"#/word/commensalism",cta:"Open the word card",title:"commensalism",roman:"kuh-MEN-suh-liz-um",body:"the relation between two different kinds of organisms when one receives benefits from the other without damaging it",clip:1},"wx-commensalism":{src:"concept:118:words:14:ex",route:"#/word/commensalism",cta:"Open the word card",title:"In a sentence · commensalism",body:"The biologist explained that the relationship between barnacles and whales is an example of commensalism, since barnacles benefit while whales are unaffected.",clip:1},"wh-commensalism":{src:"concept:118:words:14:hook",route:"#/word/commensalism",cta:"Open the word card",title:"Remember it · commensalism",body:"COMMENSAL (sharing a table) + ISM = commensalism; one guest eats well at the table, the host doesn't notice."},"wo-commensalism":{src:"lore:commensalism:0",route:"#/word/commensalism",cta:"Open the word card",title:"Where it comes from · commensalism",body:"Latin: commensalis (Latin)"},"wd-parasitism":{src:"concept:118:words:15:def",route:"#/word/parasitism",cta:"Open the word card",title:"parasitism",roman:"PAIR-uh-sih-tiz-um",body:"The relationship between two different organisms in which one organism (the parasite) benefits by living on or in the other (the host) and typically causes harm to the host in the process.",clip:1},"wx-parasitism":{src:"concept:118:words:15:ex",route:"#/word/parasitism",cta:"Open the word card",title:"In a sentence · parasitism",body:"The science teacher explained parasitism using the example of a flea living on a dog.",clip:1},"wh-parasitism":{src:"concept:118:words:15:hook",route:"#/word/parasitism",cta:"Open the word card",title:"Remember it · parasitism",body:"ParaSITISM — one creature SITS on another and takes what it needs."},"wd-predation":{src:"concept:118:words:16:def",route:"#/word/predation",cta:"Open the word card",title:"predation",roman:"pruh-DAY-shuhn",body:"an act of plundering and pillaging and marauding",clip:1},"wx-predation":{src:"concept:118:words:16:ex",route:"#/word/predation",cta:"Open the word card",title:"In a sentence · predation",body:"The wildlife documentary showed dramatic footage of predation as a hawk dove from the sky to snatch a field mouse.",clip:1},"wh-predation":{src:"concept:118:words:16:hook",route:"#/word/predation",cta:"Open the word card",title:"Remember it · predation",body:"PredATION is the ACTION of one animal hunting another — spot the word ACTION inside."},"wo-predation":{src:"lore:predation:0",route:"#/word/predation",cta:"Open the word card",title:"Where it comes from · predation",body:"Latin praedatio = plundering, from praeda = prey, booty"},"li-u113":{src:"concept:119:concept",route:"#/stop/u113",cta:"Open this stop",title:"Philosophical & Religious Vocabulary",body:"Philosophy and religion vocabulary is built almost entirely from Greek — theos (god), logos (reason), psyche (soul), kosmos (order). These are the deepest roots in the lexicon."},"lc-u113-0":{src:"concept:119:cards:0",route:"#/stop/u113",cta:"Open this stop",title:"Philosophical & Religious Vocabulary · Theology Roots",body:"Eschatology (eskhatos = last) = study of the end times. Teleology (telos = end/purpose) = study of purposes or final causes. Ontology (ontos = being) = study of the nature of being. Epistemology (episteme = knowledge) = study of how we know."},"lc-u113-1":{src:"concept:119:cards:1",route:"#/stop/u113",cta:"Open this stop",title:"Philosophical & Religious Vocabulary · Religious Practice Words",body:"Hagiography (hagios = holy + graphos) = writing about saints. Iconoclasm (eikon = image + klastes = breaker) = breaking religious images. Transubstantiation = the Catholic doctrine that bread and wine become body and blood."},"lc-u113-2":{src:"concept:119:cards:2",route:"#/stop/u113",cta:"Open this stop",title:"Philosophical & Religious Vocabulary · Philosophical -ism Words",body:"Solipsism = only the self exists. Nihilism = nothing has meaning. Utilitarianism = the greatest good for the greatest number. Consequentialism = morality judged by outcomes. Deontology (deon = duty + -logy) = morality judged by rules, not outcomes. Phenomenology = study of conscious experience."},"lc-u113-3":{src:"concept:119:cards:3",route:"#/stop/u113",cta:"Open this stop",title:"Philosophical & Religious Vocabulary · Ethics Words",body:"Altruism (alter = other) = selfless concern for others. Egoism = concern only for the self. Hedonism (hedone = pleasure) = pleasure as the highest good. Asceticism (asketes = monk) = severe self-discipline. Stoicism = endurance without complaint."},"lc-u113-4":{src:"concept:119:cards:4",route:"#/stop/u113",cta:"Open this stop",title:"Philosophical & Religious Vocabulary · Spelling Philosophical Words",body:"Eschatology = E-S-C-H-A-T-O-L-O-G-Y. Epistemology = E-P-I-S-T-E-M-O-L-O-G-Y. Transubstantiation = T-R-A-N-S-U-B-S-T-A-N-T-I-A-T-I-O-N (7 syllables!). Iconoclasm = I-C-O-N-O-C-L-A-S-M. Blasphemy = B-L-A-S-P-H-E-M-Y. Deontology = D-E-O-N-T-O-L-O-G-Y."},"uq-u113-0":{src:"unit:u113:qs:0",route:"#/stop/u113",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Philosophical & Religious Vocabulary”?",opts:["Philosophy and religion vocabulary is built almost entirely from Greek — theos (god), logos (reason), psyche (soul), kosmos (order).","Contronyms (also called autoantonyms) are words with two opposite meanings.","Latin re- = again or back.","Latin trans- = across, beyond, or through complete change."],after:"From “Philosophical & Religious Vocabulary”."}},"uq-u113-3":{src:"unit:u113:qs:3",route:"#/stop/u113",cta:"Open this stop",title:"Whose hook?",play:{q:"“TELE-OLOGY — studying the TELOS (end goal) of everything” — which word is this hook about?",opts:["teleology","eschatology","ontology","epistemology"],after:"From “Philosophical & Religious Vocabulary”."}},"wd-ontology":{src:"concept:119:words:2:def",route:"#/word/ontology",cta:"Open the word card",title:"ontology",roman:"ah-NTAH-luh-jee",body:"in computer science, a rigorous and exhaustive organization of some knowledge domain that is usually hierarchical and contains all the relevant entities and their relations",clip:1},"wx-ontology":{src:"concept:119:words:2:ex",route:"#/word/ontology",cta:"Open the word card",title:"In a sentence · ontology",body:"The philosopher spent years studying ontology to understand the fundamental nature of existence.",clip:1},"wh-ontology":{src:"concept:119:words:2:hook",route:"#/word/ontology",cta:"Open the word card",title:"Remember it · ontology",body:"ONTOlogy: to study what IS, you must grab ONTO the essence of being."},"wo-ontology":{src:"lore:ontology:0",route:"#/word/ontology",cta:"Open the word card",title:"Where it comes from · ontology",body:"Greek ontos (being) + logos (study)"},"wd-cosmology":{src:"concept:119:words:4:def",route:"#/word/cosmology",cta:"Open the word card",title:"cosmology",roman:"kaw-ZMAW-luh-jee",body:"the metaphysical study of the origin and nature of the universe",clip:1},"wx-cosmology":{src:"concept:119:words:4:ex",route:"#/word/cosmology",cta:"Open the word card",title:"In a sentence · cosmology",body:"Her fascination with cosmology led her to spend countless nights studying the formation of galaxies.",clip:1},"wh-cosmology":{src:"concept:119:words:4:hook",route:"#/word/cosmology",cta:"Open the word card",title:"Remember it · cosmology",body:"Cosmology is the LOGY of the COSMO — study the universe by studying the word itself."},"wo-cosmology":{src:"lore:cosmology:0",route:"#/word/cosmology",cta:"Open the word card",title:"Where it comes from · cosmology",body:"Greek kosmos = universe + logos = study"},"wd-hagiography":{src:"concept:119:words:5:def",route:"#/word/hagiography",cta:"Open the word card",title:"hagiography",roman:"ha-gee-AH-gruh-fee",body:"a biography that idealizes or idolizes the person (especially a person who is a saint)",clip:1},"wx-hagiography":{src:"concept:119:words:5:ex",route:"#/word/hagiography",cta:"Open the word card",title:"In a sentence · hagiography",body:"The book was criticized as pure hagiography because it never mentioned any of the leader's flaws.",clip:1},"wh-hagiography":{src:"concept:119:words:5:hook",route:"#/word/hagiography",cta:"Open the word card",title:"Remember it · hagiography",body:"Holy saints need HAGIO-GRAPHY — a HAGIO (holy) GRAPH (written) story that paints them perfectly."},"wo-hagiography":{src:"lore:hagiography:0",route:"#/word/hagiography",cta:"Open the word card",title:"Where it comes from · hagiography",body:"Greek hagios = holy + graphia = writing"},"wd-iconoclasm":{src:"concept:119:words:6:def",route:"#/word/iconoclasm",cta:"Open the word card",title:"iconoclasm",roman:"eye-KAH-nuh-kla-zuhm",body:"the orientation of an iconoclast",clip:1},"wx-iconoclasm":{src:"concept:119:words:6:ex",route:"#/word/iconoclasm",cta:"Open the word card",title:"In a sentence · iconoclasm",body:"The young artist's iconoclasm shocked the critics, who had never seen anyone so boldly reject every traditional technique.",clip:1},"wh-iconoclasm":{src:"concept:119:words:6:hook",route:"#/word/iconoclasm",cta:"Open the word card",title:"Remember it · iconoclasm",body:"ICONOCLASM — icons get a CLASM (clash/spasm of breaking): I-C-O-N-O-C-L-A-S-M."},"wo-iconoclasm":{src:"lore:iconoclasm:0",route:"#/word/iconoclasm",cta:"Open the word card",title:"Where it comes from · iconoclasm",body:"Greek eikon = image + klasma = breaking"},"wd-blasphemy":{src:"concept:119:words:8:def",route:"#/word/blasphemy",cta:"Open the word card",title:"blasphemy",roman:"BLA-sfuh-mee",body:"speech that shows deep disrespect for God or for something people hold sacred",clip:1},"wx-blasphemy":{src:"concept:119:words:8:ex",route:"#/word/blasphemy",cta:"Open the word card",title:"In a sentence · blasphemy",body:"In many ancient kingdoms, blasphemy against the temple gods brought a heavy fine.",clip:1},"wh-blasphemy":{src:"concept:119:words:8:hook",route:"#/word/blasphemy",cta:"Open the word card",title:"Remember it · blasphemy",body:"BLASPHEMY has 'phemy' not 'phamy' — think 'phemy' sounds like 'fame', and saying bad things ruins God's fame."},"wo-blasphemy":{src:"lore:blasphemy:0",route:"#/word/blasphemy",cta:"Open the word card",title:"Where it comes from · blasphemy",body:"Greek blasphemia = evil speech"},"wd-altruism":{src:"concept:119:words:14:def",route:"#/word/altruism",cta:"Open the word card",title:"altruism",roman:"A-ltroo-ih-zuhm",body:"the quality of unselfish concern for the welfare of others",clip:1},"wx-altruism":{src:"concept:119:words:14:ex",route:"#/word/altruism",cta:"Open the word card",title:"In a sentence · altruism",body:"Her altruism was evident when she donated her entire birthday money to help families affected by the flood.",clip:1},"wh-altruism":{src:"concept:119:words:14:hook",route:"#/word/altruism",cta:"Open the word card",title:"Remember it · altruism",body:"ALTRUism puts ALTeR-ego first — think of the 'other' (alter) before yourself: A-L-T-R-U-I-S-M."},"wo-altruism":{src:"lore:altruism:0",route:"#/word/altruism",cta:"Open the word card",title:"Where it comes from · altruism",body:"French autrui = other people, from Latin alter = other"},"wd-hedonism":{src:"concept:119:words:15:def",route:"#/word/hedonism",cta:"Open the word card",title:"hedonism",roman:"HEE-duh-nih-zuhm",body:"the pursuit of pleasure as a matter of ethical principle",clip:1},"wx-hedonism":{src:"concept:119:words:15:ex",route:"#/word/hedonism",cta:"Open the word card",title:"In a sentence · hedonism",body:"The philosopher argued that a life devoted entirely to hedonism would ultimately feel hollow and meaningless without deeper purpose.",clip:1},"wh-hedonism":{src:"concept:119:words:15:hook",route:"#/word/hedonism",cta:"Open the word card",title:"Remember it · hedonism",body:"HEDonism: HE Does Only Nice indulgences — seeking maximum pleasure."},"wo-hedonism":{src:"lore:hedonism:0",route:"#/word/hedonism",cta:"Open the word card",title:"Where it comes from · hedonism",body:"Greek hedone = pleasure"},"wo-asceticism":{src:"lore:asceticism:0",route:"#/word/asceticism",cta:"Open the word card",title:"Where it comes from · asceticism",body:"Greek askesis = exercise, training, from askein = to work or practice"},"pq-w31":{src:"trivia:w31",route:"#/word/mellifluous",cta:"Open “mellifluous”",title:"What does it mean?",play:{q:"What does “mellifluous” mean?",opts:["sweetly or smoothly flowing","A stinging Central American ant once brought to the southern U.S. to fight the boll weevil.","of or relating to or resembling gladiators or their combat","tending to replace or take the place of something"],after:"Example: The singer's mellifluous voice flowed through the hall like warm honey."}},"pq-w37":{src:"trivia:w37",route:"#/word/intensity",cta:"Open “intensity”",title:"What does it mean?",play:{q:"What does “intensity” mean?",opts:["the amount of energy transmitted (as by acoustic or electromagnetic radiation)","tending to promote or preserve health","a valley, especially a broad one (a poetic word)","a common nonmetallic element that constitutes 78 percent of the atmosphere"],after:"Example: He adjusted the intensity of the sound."}},"pq-w67":{src:"trivia:w67",route:"#/word/insulation",cta:"Open “insulation”",title:"What does it mean?",play:{q:"What does “insulation” mean?",opts:["material that slows the passage of heat electricity or sound","a room where books are kept","to cause confusion and shame to","combine so as to form a more complex, product"],after:"Example: The insulation of England was preserved by the English Channel."}},"pq-w72":{src:"trivia:w72",route:"#/word/bayou",cta:"Open “bayou”",title:"What does it mean?",play:{q:"What does “bayou” mean?",opts:["a marshy arm of a river usually sluggish or stagnant","having no bearing on or connection with the subject at issue","call before a court to answer an indictment","a follower or advocate of Carl Jung's theories"],after:"Example: Spanish moss hung from the cypress trees along the murky, still bayou at the edge of town."}},"pq-w75":{src:"trivia:w75",route:"#/word/gourmet",cta:"Open “gourmet”",title:"What does it mean?",play:{q:"What does “gourmet” mean?",opts:["a connoisseur of fine food and drink","To hand in something for others to review, or to give in to authority","a stand with a slanted top used to hold a speech or book","a cow over one year old that has not produced a calf"],after:"Example: The self-described gourmet spent an entire Saturday searching the market for the finest imported truffles."}},"pq-w79":{src:"trivia:w79",route:"#/word/hexameter",cta:"Open “hexameter”",title:"What does it mean?",play:{q:"What does “hexameter” mean?",opts:["a verse line having six metrical feet","of or relating to a belief in sacerdotalism","a conservative who subscribes to neoconservatism","the force of policemen and officers"],after:"Example: Homer's epic poems were composed in the powerful rhythm of dactylic hexameter."}},"pq-w81":{src:"trivia:w81",route:"#/word/nausea",cta:"Open “nausea”",title:"What does it mean?",play:{q:"What does “nausea” mean?",opts:["sickness at the stomach especially when loathing food","being essential indispensable","in a disappointing manner","work in an administrative capacity; supervise or be in charge of"],after:"Example: The rough waves on the ocean caused a wave of nausea to wash over the young sailor."}},"pq-w98":{src:"trivia:w98",route:"#/word/mirage",cta:"Open “mirage”",title:"What does it mean?",play:{q:"What does “mirage” mean?",opts:["something illusory without substance or reality","Ways of sharing news and information, like TV, radio, newspapers, and the internet.","acts of formally giving up a throne, position, or power","a Japanese three-line, seventeen-syllable poem about human nature and humor"],after:"Example: Exhausted and thirsty, the hiker saw what he thought was a lake ahead, but it was only a mirage."}},"pq-w133":{src:"trivia:w133",route:"#/word/defendant",cta:"Open “defendant”",title:"What does it mean?",play:{q:"What does “defendant” mean?",opts:["a person against whom a charge is brought in court","natives or residents of Pennsylvania","designed to find information or ascertain facts","given or giving freely"],after:"Example: The defendant sat quietly beside his lawyer as the jury filed into the courtroom to deliver its verdict."}},"pq-w148":{src:"trivia:w148",route:"#/word/pizza",cta:"Open “pizza”",title:"What does it mean?",play:{q:"What does “pizza” mean?",opts:["a flat baked pie of Italian origin with various ingredients and toppings","to replace in power or acceptance","to go beyond the limits of; to be greater in scope or significance than","distribute according to a plan or set apart for a special purpose"],after:"Example: They ordered a pizza loaded with mushrooms, peppers, and extra cheese for movie night."}},"pq-w153":{src:"trivia:w153",route:"#/word/rhyme",cta:"Open “rhyme”",title:"What does it mean?",play:{q:"What does “rhyme” mean?",opts:["a word agreeing with another word in terminal sound","Complete and total; also done openly, at once, or without holding back.","To build something again after it has been damaged or destroyed","the main organ of photosynthesis and transpiration in higher plants"],after:"Example: The young poet spent an entire afternoon searching for a word that would rhyme with 'orange,' only to discover that almost nothing in English does."}},"pq-w162":{src:"trivia:w162",route:"#/word/janitor",cta:"Open “janitor”",title:"What does it mean?",play:{q:"What does “janitor” mean?",opts:["a person employed to keep things clean","separate (substances) into constituent elements or parts","a party of people wearing masks and other disguises","a person who meddles in the affairs of others"],after:"Example: The school janitor mopped the hallway floors every evening so that students would arrive to a sparkling clean building the next morning."}},"pq-w165":{src:"trivia:w165",route:"#/word/sausage",cta:"Open “sausage”",title:"What does it mean?",play:{q:"What does “sausage” mean?",opts:["highly seasoned ground meat that is stuffed in casings which are tied shut at both ends","chocolate that contains at least 32 percent cocoa butter","A school system where advanced students teach younger pupils under one teacher's supervision.","interpret falsely"],after:"Example: The smell of sizzling sausage drifting from the kitchen made everyone rush downstairs for breakfast."}}});
